static size_t xstrsncpy(char *dst, const char *src, size_t n)
{
	char *end = memccpy(dst, src, '\0', n);

	if (!end) {
		dst[n - 1] = '\0';
		end = dst + n;
	}

	return end - dst; /* includes NUL */
}

static inline size_t xstrlen(const char *s)
{
	return strlen(s);
}

static char *xitoa(long long val)
{
	static char dst[32] = {'\0'};
	static const char digits[201] =
		"0001020304050607080910111213141516171819"
		"2021222324252627282930313233343536373839"
		"4041424344454647484950515253545556575859"
		"6061626364656667686970717273747576777879"
		"8081828384858687888990919293949596979899";
	unsigned long long uval = (val < 0) ? (unsigned long long)(-val) : (unsigned long long)val;
	int i = 30;

	dst[31] = '\0';
	if (uval == 0) {
		dst[30] = '0';
		i = 29;
	}
	while (uval >= 100) {
		unsigned idx = (uval % 100) * 2;
		uval /= 100;
		dst[i] = digits[idx + 1];
		dst[i - 1] = digits[idx];
		i -= 2;
	}
	if (uval >= 10) {
		unsigned idx = uval * 2;
		dst[i] = digits[idx + 1];
		dst[i - 1] = digits[idx];
		i -= 2;
	} else if (uval) {
		dst[i] = (char)('0' + uval);
		--i;
	}
	if (val < 0) {
		dst[i] = '-';
		--i;
	}
	return &dst[i + 1];
}

