/* ---------------------------------------------------------------- */
/* Directory listing                                                 */
/* ---------------------------------------------------------------- */

static char *pnamebuf_end;
static size_t pnamebuflen;

static int nftw_fn(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf);
static blkcnt_t ent_blocks_acc;
static ullong_t ent_files_acc;
static dev_t du_dev;
#define HASH_BITS 0x3FFFFF
static unsigned long *ihashbmp;

static bool test_set_bit(ullong_t nr)
{
	nr &= HASH_BITS;

	unsigned long *m = ((unsigned long *)ihashbmp) + (nr >> 6);

	if (*m & (1UL << (nr & 63)))
		return FALSE;

	*m |= 1UL << (nr & 63);

	return TRUE;
}

static int nftw_fn(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf)
{
	(void)fpath;
	(void)ftwbuf;

	if (sb->st_dev != du_dev)
		return FTW_CONTINUE;

	if (typeflag == FTW_D || typeflag == FTW_DP || typeflag == FTW_DNR) {
		/* count dir size too */
	}

	if (sb->st_nlink > 1) {
		if (!test_set_bit(((ullong_t)sb->st_dev << 32) ^ sb->st_ino))
			return FTW_CONTINUE;
	}

	ent_blocks_acc += cfg.apparentsz ? sb->st_size : sb->st_blocks;
	++ent_files_acc;

	return FTW_CONTINUE;
}

static void du_path(const char *path, blkcnt_t *blocks, ullong_t *files)
{
	ent_blocks_acc = 0;
	ent_files_acc = 0;
	nftw(path, nftw_fn, 64, FTW_MOUNT | FTW_PHYS | FTW_ACTIONRETVAL);
	*blocks = ent_blocks_acc;
	*files = ent_files_acc;
}

static int dentfill(char *path, struct entry **ppdents)
{
	uchar_t entflags = 0;
	struct dirent *dp;
	char *namep;
	struct entry *dentp;
	size_t off = 0;
	struct stat sb_path, sb;
	DIR *dirp = opendir(path);

	ndents = 0;
	gtimesecs = time(NULL);

	if (!dirp)
		return 0;

	int fd = dirfd(dirp);

	if (cfg.blkorder) {
		num_files = 0;
		dir_blocks = 0;

		if (fstatat(fd, path, &sb_path, 0) == -1)
			goto exit;

		du_dev = sb_path.st_dev;
