			ihashbmp = calloc(1, HASH_BITS >> 3);
			if (!ihashbmp)
				goto exit;
		} else
			memset(ihashbmp, 0, HASH_BITS >> 3);
	}

	while ((dp = readdir(dirp))) {
		namep = dp->d_name;

		/* Skip self and parent */
		if (namep[0] == '.' && (namep[1] == '\0' || (namep[1] == '.' && namep[2] == '\0')))
			continue;

