					num_files += f;
				}
			} else {
				if (sb.st_nlink <= 1 || test_set_bit(((ullong_t)sb.st_dev << 32) ^ sb.st_ino)) {
					dir_blocks += (cfg.apparentsz ? sb.st_size : sb.st_blocks);
					++num_files;
				}
			}
			continue;
		}

		entflags = 0;
		if (fstatat(fd, namep, &sb, AT_SYMLINK_NOFOLLOW) == -1) {
			memset(&sb, 0, sizeof(struct stat));
			entflags = FILE_MISSING;
		}

		if (ndents == total_dents) {
			total_dents += ENTRY_INCR;
			*ppdents = realloc(*ppdents, total_dents * sizeof(**ppdents));
			if (!*ppdents)
				exit(1);
		}

		/* realloc() may result in memory move, we must re-adjust if that happens */
		if (pnamebuflen - off < NAME_MAX + 1) {
			char *pnb = pnamebuf;

			pnamebuflen += NAMEBUF_INCR;
			pnamebuf = realloc(pnamebuf, pnamebuflen);
			if (!pnamebuf)
				exit(1);

			if (pnb != pnamebuf) {
				dentp = *ppdents;
				dentp->name = pnamebuf;

				for (int count = 1; count < ndents; ++dentp, ++count)
					/* Current file name starts at last file name start + length */
					(dentp + 1)->name = (char *)((size_t)dentp->name + dentp->nlen);
			}
		}

		dentp = *ppdents + ndents;

		/* Selection file name */
		dentp->name = (char *)((size_t)pnamebuf + off);
		dentp->nlen = xstrsncpy(dentp->name, namep, NAME_MAX + 1);
		off += dentp->nlen;

		/* Copy other fields */
		struct stat *psb = &sb;
		struct stat sbt;
		bool islnk = S_ISLNK(sb.st_mode);
		bool lnkok = FALSE;

		if (islnk && fstatat(fd, namep, &sbt, 0) == 0) {
			lnkok = TRUE;
			psb = &sbt;
		}

		if (gcfg_timetype_mod()) {
			dentp->sec = psb->st_mtime;
			dentp->nsec = (uint_t)psb->st_mtim.tv_nsec;
		} else if (cfg.timetype == T_ACCESS) {
			dentp->sec = psb->st_atime;
			dentp->nsec = (uint_t)psb->st_atim.tv_nsec;
		} else {
			dentp->sec = psb->st_ctime;
			dentp->nsec = (uint_t)psb->st_ctim.tv_nsec;
		}

		if ((gtimesecs - psb->st_ctime <= YOUNG_SECS) && (gtimesecs - psb->st_ctime >= 0))
			entflags |= FILE_YOUNG;
		else if ((gtimesecs - psb->st_mtime <= YOUNG_SECS) && (gtimesecs - psb->st_mtime >= 0))
			entflags |= FILE_YOUNG;

		if (islnk) {
			dentp->mode = S_IFLNK | (psb->st_mode & 07777);
			dentp->size = 0;
		} else {
			dentp->mode = sb.st_mode;
			dentp->size = sb.st_size;
		}

		dentp->uid = sb.st_uid;
		dentp->gid = sb.st_gid;

		if (cfg.blkorder) {
			if (S_ISDIR(sb.st_mode)) {
				blkcnt_t b = 0;
				ullong_t f = 0;

				if (sb_path.st_dev == sb.st_dev) {
					char tmppath[PATH_MAX];

					mkpath(path, namep, tmppath);
					du_path(tmppath, &b, &f);
				}
				dentp->blocks = b;
				dir_blocks += b;
				num_files += f;
			} else {
				dentp->blocks = (cfg.apparentsz ? sb.st_size : sb.st_blocks);
				if (sb.st_nlink <= 1 || test_set_bit(((ullong_t)sb.st_dev << 32) ^ sb.st_ino)) {
					dir_blocks += dentp->blocks;
					++num_files;
				}
			}
		} else
			dentp->blocks = sb.st_blocks;

		if (islnk) {
			if (lnkok) {
				if (S_ISDIR(sbt.st_mode))
					entflags |= DIR_OR_DSLNK;
			} else
				entflags |= SYM_ORPHAN;
		} else if (S_ISDIR(sb.st_mode))
			entflags |= DIR_OR_DSLNK;
		else if (S_ISREG(sb.st_mode) && sb.st_nlink > 1)
			entflags |= HARD_LINK;

		dentp->flags = entflags;
		++ndents;
	}

exit:
	if (cfg.blkorder)
		;
	closedir(dirp);
	return ndents;
}

static int dentfind(const char *fname, int n)
{
	for (int i = 0; i < n; ++i)
		if (strcmp(fname, pdents[i].name) == 0)
			return i;

	return -1;
}

