static dev_t du_dev;
#define HASH_BITS 0x3FFFFF
static unsigned long *ihashbmp;

static bool test_set_bit(ullong_t nr)
{
	nr &= HASH_BITS;

	unsigned long *m = ((unsigned long *)ihashbmp) + (nr >> 6);

	if (*m & (1UL << (nr & 63)))
		return FALSE;

	*m |= 1UL << (nr & 63);

	return TRUE;
}

static int nftw_fn(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf)
{
	(void)fpath;
	(void)ftwbuf;

	if (sb->st_dev != du_dev)
