			return FTW_CONTINUE;
	}

	ent_blocks_acc += cfg.apparentsz ? sb->st_size : sb->st_blocks;
	++ent_files_acc;

	return FTW_CONTINUE;
}

static void du_path(const char *path, blkcnt_t *blocks, ullong_t *files)
{
	ent_blocks_acc = 0;
	ent_files_acc = 0;
