{"command":"cat >> /workspace/src/nnn.c <<'EOF'
/* ---------------------------------------------------------------- */
/* Process spawning                                                  */
/* ---------------------------------------------------------------- */

#define EXEC_ARGS_MAX 10

static void exitcurses(void)
{
	endwin();
	fflush(stdout);
}

static bool initcurses(void *oldmask);

/* Splits command string into args, honouring single and double quotes */
static int parseargs(char *cmd, char **argv, int *pindex)
{
	int count = 0;
	size_t len = xstrlen(cmd) + 1;
	char *line = cmd, *end = cmd + len - 1;

	(void)pindex;
	while (line < end) {
		while (*line == ' ' || *line == '\t')
			++line;
		if (line >= end || !*line)
			break;

		if (count >= EXEC_ARGS_MAX - 1)
			return -1;

		if (*line == '\'' || *line == '"') {
			char q = *line++;

			argv[count++] = line;
			while (*line && *line != q)
				++line;
			if (*line)
				*line++ = '\0';
		} else {
			argv[count++] = line;
			while (*line && *line != ' ' && *line != '\t')
				++line;
			if (*line)
				*line++ = '\0';
		}
	}

	return count;
}

static int spawn(char *file, char *arg1, char *arg2, char *arg3, ushort flag)
{
	pid_t pid;
	int status = 0, retstatus = 0xFFFF;
	char *argv[EXEC_ARGS_MAX] = {0};
	char *cmd = NULL;

	if (!file || !*file)
		return retstatus;

	/* Swap args if the first arg is NULL and the other 2 aren't */
	if (!arg1 && arg2) {
		arg1 = arg2;
		if (arg3) {
			arg2 = arg3;
			arg3 = NULL;
		} else
			arg2 = NULL;
	}

	if (flag & F_MULTI) {
		size_t len = xstrlen(file) + 1;

		cmd = (char *)malloc(len);
		if (!cmd)
			return retstatus;

		xstrsncpy(cmd, file, len);
		status = parseargs(cmd, argv, NULL);
		if (status <= 0 || status > (EXEC_ARGS_MAX - 4)) { /* 3 args and last NULL */
			free(cmd);
			return retstatus;
		}
	} else
		argv[status++] = file;

	argv[status] = arg1;
	argv[++status] = arg2;
	argv[++status] = arg3;

	if (flag & F_NORMAL)
		exitcurses();

	pid = fork();
	if (pid == 0) {
		/* Suppress stdout and stderr */
		if (flag & F_NOTRACE) {
