{
	const char *start, *end;
	int fd = create_tmp_file();

	if (fd == -1)
		return;

	char *prog = getenv("NNN_HELP");

	if (prog && *prog) {
		/* Run the help program and capture its output */
		pid_t pid = fork();

		if (pid == 0) {
			dup2(fd, STDOUT_FILENO);
			dup2(fd, STDERR_FILENO);
			execl("/bin/sh", "sh", "-c", prog, (char *)NULL);
