	(void)start;
	(void)end;
	{
		char avail[16], used[16];

		xstrsncpy(avail, coolsize(get_fs_size(path, VFS_AVAIL)), sizeof(avail));
		xstrsncpy(used, coolsize(get_fs_size(path, VFS_USED)), sizeof(used));
		dprintf(fd, "\nVOLUME: avail:%s used:%s size:%s\n\n", avail, used,
			coolsize(get_fs_size(path, VFS_SIZE)));
	}

	if (bookmark && maxbm && bookmark[0].key) {
		dprintf(fd, "BOOKMARKS\n");
		printkv_fd(fd, bookmark, maxbm, TRUE);
		dprintf(fd, "\n");
	}

	if (plug && maxplug && plug[0].key) {
		dprintf(fd, "PLUGIN KEYS\n");
		printkv_fd(fd, plug, maxplug, FALSE);
		dprintf(fd, "\n");
	}

	for (size_t i = 0; i < ELEMENTS(env_help_vars); ++i) {
		char *v = getenv(env_help_vars[i]);

		if (v)
			dprintf(fd, "%s: %s\n", env_help_vars[i], v);
	}

	if (selpath)
		dprintf(fd, "SELECTION FILE: %s\n", selpath);

	dprintf(fd, "\nv%s\n%s\n", VERSION, GENERAL_INFO);
	close(fd);

	spawn(pager, g_tmpfpath, NULL, NULL, F_CLI | F_TTY);
	unlink(g_tmpfpath);
}

