static char **pop_lines;
static int pop_nlines;

static void free_pop_lines(void)
{
	for (int i = 0; i < pop_nlines; ++i)
		free(pop_lines[i]);
	free(pop_lines);
	pop_lines = NULL;
	pop_nlines = 0;
