static void add_pop_line(const char *s, size_t len)
{
	pop_lines = realloc(pop_lines, sizeof(char *) * (pop_nlines + 1));
	pop_lines[pop_nlines] = strndup(s, len);
	++pop_nlines;
}

/* Run a command and collect all output lines */
static void collect_output(char *const argv[])
{
	int pipefd[2];

	if (pipe(pipefd) == -1)
		return;

	pid_t pid = fork();

	if (pid == 0) {
		close(pipefd[0]);
		dup2(pipefd[1], STDOUT_FILENO);
		int fd = open("/dev/null", O_WRONLY);
		if (fd != -1) {
			dup2(fd, STDERR_FILENO);
			close(fd);
		}
		close(pipefd[1]);
		execvp(argv[0], argv);
		_exit(EXIT_FAILURE);
	}

	close(pipefd[1]);
	if (pid < 0) {
		close(pipefd[0]);
		return;
	}

	char *buf = NULL;
	size_t len = 0, cap = 0;
	ssize_t r;
	char tmp[4096];

	while ((r = read(pipefd[0], tmp, sizeof(tmp))) > 0) {
		if (len + r + 1 > cap) {
			cap = (len + r + 1) * 2;
			buf = realloc(buf, cap);
		}
		memcpy(buf + len, tmp, r);
		len += r;
	}
	close(pipefd[0]);
	waitpid(pid, NULL, 0);

	if (!buf)
		return;
	buf[len] = '\0';

	char *p = buf, *end = buf + len;

	while (p < end) {
		char *nl = memchr(p, '\n', end - p);

		if (!nl) {
			add_pop_line(p, end - p);
			break;
		}
		add_pop_line(p, nl - p);
		p = nl + 1;
	}
	free(buf);
}

static const char popup_footer[] = "q/ESC:close  arrows:scroll  n/j:next  p/k:prev";

/* Returns TRUE if ok */
static bool show_stats(const char *path)
{
	char fpath[PATH_MAX];
	int voff = 0, hoff = 0;
	bool reload = TRUE;

	if (!ndents)
		return TRUE;

	while (1) {
		getmaxyx(stdscr, xlines, xcols);

		if (reload) {
			free_pop_lines();
			mkpath(path, pdents[cur].name, fpath);

			char *sargv[] = {"stat", "--", fpath, NULL};

			collect_output(sargv);
			voff = hoff = 0;
			reload = FALSE;
		}

		int H = MAX(5, MIN(20, xlines - 4));
		int W = MAX(20, (xcols * 3) / 4);

		if (xcols < 20 || W > xcols || H > xlines) {
			free_pop_lines();
			return TRUE;
		}

		int y = (xlines - H) / 2, x = (xcols - W) / 2;
		int inner = W - 2;
		int maxlen = 0;

		for (int i = 0; i < pop_nlines; ++i) {
			int l = (int)strlen(pop_lines[i]);

			if (l > maxlen)
				maxlen = l;
		}

		int maxhoff = MAX(0, maxlen - inner);
		int page = H - 3;
		int maxvoff = MAX(0, pop_nlines - page);

		if (voff > maxvoff)
			voff = maxvoff;
		if (hoff > maxhoff)
			hoff = maxhoff;

		WINDOW *win = newwin(H, W, y, x);

		if (!win) {
			free_pop_lines();
			return TRUE;
		}

		keypad(win, TRUE);
		box(win, 0, 0);

		mvwprintw(win, 0, 2, " %d/%d ", cur + 1, ndents);
		wattron(win, A_BOLD);
		waddstr(win, pdents[cur].name);
		wattroff(win, A_BOLD);
		waddch(win, ' ');

		for (int r = 0; r < H - 4; ++r) {
			int li = voff + r;

			if (li >= pop_nlines)
				break;

			const char *s = pop_lines[li];
			int l = (int)strlen(s);

			if (hoff < l)
				mvwaddnstr(win, 2 + r, 1, s + hoff, inner);
		}

		if (voff > 0)
			mvwaddch(win, 1, W - 2, '^');
		if (voff + page < pop_nlines)
			mvwaddch(win, H - 3, W - 2, 'v');
		if (hoff > 0)
			mvwaddch(win, H - 2, 1, '<');
		if (hoff < maxhoff)
			mvwaddch(win, H - 2, W - 2, '>');

		mvwaddnstr(win, H - 1, 1, popup_footer, W - 1);
		wrefresh(win);

		int c = wgetch(win);

		delwin(win);

		switch (c) {
		case 'q':
		case ESC:
			free_pop_lines();
			return TRUE;
		case KEY_RESIZE:
			touchwin(stdscr);
			redraw((char *)path);
			refresh();
			break;
		case KEY_UP:
			if (voff > 0)
				--voff;
			break;
		case KEY_DOWN:
			if (voff < maxvoff)
				++voff;
			break;
		case KEY_PPAGE:
			voff = MAX(0, voff - page);
			break;
		case KEY_NPAGE:
			voff = MIN(maxvoff, voff + page);
			break;
		case KEY_HOME:
			voff = 0;
			break;
		case KEY_END:
			voff = maxvoff;
			break;
		case KEY_LEFT:
			hoff = MAX(0, hoff - 10);
			break;
		case KEY_RIGHT:
			hoff = MIN(maxhoff, hoff + 10);
			break;
		case 'j':
		case 'n':
			if (gcfg.rollover || cur != ndents - 1) {
				move_cursor((cur + 1) % ndents, 0);
				reload = TRUE;
			}
			break;
		case 'k':
		case 'p':
			if (gcfg.rollover || cur) {
				move_cursor((cur + ndents - 1) % ndents, 0);
				reload = TRUE;
			}
			break;
		default:
			break;
		}
	}
}

