/* ---------------------------------------------------------------- */
/* Main loop helpers                                                 */
/* ---------------------------------------------------------------- */

static int nextsel(int presel)
{
	int c = presel;
	uint_t i;
	bool escaped = FALSE;

	if (c == 0 || c == MSGWAIT) {
try_quit:
		c = getch();

		if (c == KEY_RESIZE) {
			getmaxyx(stdscr, xlines, xcols);
		}

		/* Handle Alt+key */
		if (c == ESC) {
			timeout(0);
			c = getch();
			if (c != ERR) {
				if (c == ESC)
					c = CONTROL('L');
				else {
					ungetch(c);
					c = ';';
				}
				settimeout();
			} else if (escaped) {
				settimeout();
				c = CONTROL('Q');
			} else {
				escaped = TRUE;
				settimeout();
				goto try_quit;
			}
		}

		if (c == ERR && presel == MSGWAIT)
			c = (cfg.filtermode || g_state.picker) ? FILTER : CONTROL('L');
		else if (c == FILTER || c == CONTROL('L'))
			/* Clear previous filter when manually starting */
			g_ctx[gcfg.curctx].c_fltr[1] = '\0';
	}

	if (c == -1) {
		++idle;

		if (!cfg.blkorder && inotify_wd >= 0 && (idle & 1)) {
			struct inotify_event *event;
			char inotify_buf[4096] __attribute__((aligned(__alignof__(struct inotify_event))));
			ssize_t n = read(inotify_fd, inotify_buf, sizeof(inotify_buf));

			if (n > 0) {
				for (char *ptr = inotify_buf; ptr < inotify_buf + n;
				     ptr += sizeof(struct inotify_event) + event->len) {
					event = (struct inotify_event *)ptr;
					if (!event->wd)
						break;
					if (event->mask & (IN_ATTRIB | IN_CREATE | IN_DELETE | IN_DELETE_SELF
							   | IN_MODIFY | IN_MOVE_SELF | IN_MOVED_FROM | IN_MOVED_TO)) {
						c = CONTROL('L');
						break;
					}
				}
			}
		}

		if (idletimeout && idle == idletimeout) {
			idle = 0;
			c = '0';
		}
	} else
		idle = 0;

	for (i = 0; i < ELEMENTS(bindings); ++i)
		if (c == bindings[i].sym)
			return bindings[i].act;

	return 0;
}

static inline bool filterset(void)
{
	char *fltr = g_ctx[gcfg.curctx].c_fltr;

	return (fltr[0] == FILTER || fltr[0] == RFILTER) && fltr[1];
}

static inline void clearfilter(void)
{
	char *fltr = g_ctx[gcfg.curctx].c_fltr;

	if (fltr[1]) {
		fltr[REGEX_MAX - 1] = fltr[1];
		fltr[1] = '\0';
	}
}

static void copycurname(void)
{
	if (ndents)
		xstrsncpy(g_ctx[gcfg.curctx].c_name, pdents[cur].name, NAME_MAX + 1);
	else
		g_ctx[gcfg.curctx].c_name[0] = '\0';
}

static const char *filtername(void)
{
	return (filtertype == 2) ? "reg" : ((filtertype == 1) ? "fzy" : "str");
}

static void clearinfoln(void)
{
	move(xlines - 2, 0);
	clrtoeol();
}

static void showfilterinfo(void)
{
	int i = 0;
	char info[REGEX_MAX] = "\0\0\0\0\0";

	i = getorderstr(info);
	if (i)
		++i;

	snprintf(info + i, REGEX_MAX - i - 1, "  %s [/], %s [:]",
		 filtername(), (fnstrstr == &strcasestr) ? "ic" : "noic");

	clearinfoln();
	mvaddstr(xlines - 2, xcols - xstrlen(info), info);
}

static void printprompt(const char *str)
{
	clearprompt();
	if (xstrlen(str) < (size_t)xcols)
		addstr(str);
}

static void setfilterprefix(char *ln)
{
	ln[0] = (filtertype == 2) ? RFILTER : FILTER;
}

static int filterentries(char *path, char *lastname)
{
	wchar_t *wln = (wchar_t *)alloca(sizeof(wchar_t) * REGEX_MAX);
	char *ln = g_ctx[gcfg.curctx].c_fltr;
	wint_t ch[1];
	int r, total = ndents, len;
	char *pln = g_ctx[gcfg.curctx].c_fltr + 1;

	if (ndents && (ln[0] == FILTER || ln[0] == RFILTER) && *pln) {
		if (matches(pln) != -1) {
			move_cursor(dentfind(lastname, ndents), 0);
			redraw(path);
		}

		if (!cfg.filtermode) {
			statusbar(path);
			return 0;
		}

		len = mbstowcs(wln, ln, REGEX_MAX);
	} else {
		setfilterprefix(ln);
		wln[0] = (uchar_t)ln[0];
		ln[1] = wln[1] = '\0';
		len = 1;
	}

	cleartimeout();
	curs_set(TRUE);
	showfilterinfo();
	printprompt(ln);

	while ((r = get_wch(ch)) != ERR) {
		switch (*ch) {
		case KEY_RESIZE:
			clearoldprompt();
			redraw(path);
			showfilterinfo();
			printprompt(ln);
			continue;
		case KEY_DC: // fallthrough
		case KEY_BACKSPACE: // fallthrough
		case '\b': // fallthrough
		case DEL: /* handle DEL */
			if (len != 1) {
				wln[--len] = '\0';
				wcstombs(ln, wln, REGEX_MAX);
				ndents = total;
			} else {
				*ch = FILTER;
				goto end;
			}
			// fallthrough
		case CONTROL('L'):
			if (*ch == CONTROL('L')) {
				if (wln[1]) {
					ln[REGEX_MAX - 1] = ln[1];
					ln[1] = wln[1] = '\0';
					len = 1;
					ndents = total;
				} else if (ln[REGEX_MAX - 1]) { /* Show the previous filter */
					ln[1] = ln[REGEX_MAX - 1];
					ln[REGEX_MAX - 1] = '\0';
					len = mbstowcs(wln, ln, REGEX_MAX);
				} else
					goto end;
			}

			/* Go to the top, we don't know if the hovered file will match the filter */
			cur = 0;

			if (matches(pln) != -1)
				redraw(path);

			showfilterinfo();
			printprompt(ln);
			continue;
		case KEY_MOUSE:
			goto end;
		case ESC:
			timeout(0);
			r = get_wch(ch);
			cleartimeout();
			if (r != ERR) {
				if (*ch == ESC) /* Handle Alt+Esc */
					*ch = 'q'; /* Quit context */
				else {
					unget_wch(*ch);
					*ch = ';'; /* Run plugin */
				}
			} else
				*ch = ESC;
			goto end;
		}

		if (r != OK) /* Handle Fn keys in main loop */
			break;

		/* Handle all control chars in main loop */
		if (*ch < 128 && keyname(*ch)[0] == '^' && *ch != '^')
			goto end;

		if (len == 1) {
			if (*ch == '?') /* Help and config key, '?' is an invalid regex */
				goto end;

			if (cfg.filtermode) {
				switch (*ch) {
				case '\'': // fallthrough /* Go to first non-dir file */
				case '+': // fallthrough /* Toggle file selection */
				case ',': // fallthrough /* Mark CWD */
				case '-': // fallthrough /* Visit last visited dir */
				case '.': // fallthrough /* Show hidden files */
				case ';': // fallthrough /* Run plugin key */
				case '=': // fallthrough /* Launch app */
				case '>': // fallthrough /* Export file list */
				case '@': // fallthrough /* Visit start dir */
				case ']': // fallthorugh /* Prompt key */
				case '`': // fallthrough /* Visit / */
				case '~': /* Go HOME */
					goto end;
				}
			}

			/* Toggle case-sensitivity */
			if (*ch == CASE) {
				fnstrstr = (fnstrstr == &strcasestr) ? &strstr : &strcasestr;
				regflags ^= REG_ICASE;
				showfilterinfo();
				printprompt(ln);
				continue;
			}

			/* Toggle string or regex filter */
			if (*ch == FILTER) {
