/* ---------------------------------------------------------------- */
/* Main loop helpers                                                 */
/* ---------------------------------------------------------------- */

static int nextsel(int presel)
{
	int c = presel;
	uint_t i;
	bool escaped = FALSE;

	if (c == 0 || c == MSGWAIT) {
try_quit:
		c = getch();

		if (c == KEY_RESIZE) {
			getmaxyx(stdscr, xlines, xcols);
		}

		/* Handle Alt+key */
		if (c == ESC) {
			timeout(0);
			c = getch();
			if (c != ERR) {
				if (c == ESC)
					c = CONTROL('L');
				else {
					ungetch(c);
					c = ';';
				}
				settimeout();
			} else if (escaped) {
				settimeout();
				c = CONTROL('Q');
			} else {
				escaped = TRUE;
				settimeout();
				goto try_quit;
			}
		}

		if (c == ERR && presel == MSGWAIT)
			c = (cfg.filtermode || g_state.picker) ? FILTER : CONTROL('L');
		else if (c == FILTER || c == CONTROL('L'))
			/* Clear previous filter when manually starting */
			g_ctx[gcfg.curctx].c_fltr[1] = '\0';
	}

	if (c == -1) {
		++idle;

		if (!cfg.blkorder && inotify_wd >= 0 && (idle & 1)) {
			struct inotify_event *event;
			char inotify_buf[4096] __attribute__((aligned(__alignof__(struct inotify_event))));
			ssize_t n = read(inotify_fd, inotify_buf, sizeof(inotify_buf));

			if (n > 0) {
				for (char *ptr = inotify_buf; ptr < inotify_buf + n;
				     ptr += sizeof(struct inotify_event) + event->len) {
					event = (struct inotify_event *)ptr;
					if (!event->wd)
						break;
					if (event->mask & (IN_ATTRIB | IN_CREATE | IN_DELETE | IN_DELETE_SELF
							   | IN_MODIFY | IN_MOVE_SELF | IN_MOVED_FROM | IN_MOVED_TO)) {
						c = CONTROL('L');
						break;
					}
				}
			}
		}

		if (idletimeout && idle == idletimeout) {
			idle = 0;
			c = '0';
		}
	} else
		idle = 0;

	for (i = 0; i < ELEMENTS(bindings); ++i)
		if (c == bindings[i].sym)
			return bindings[i].act;

	return 0;
