static char *get_kv_val(kv *kvarr, char *buf, int key, uchar_t max, bool bm)
{
	if (!kvarr)
		return NULL;

	for (int r = 0; r < max && kvarr[r].key; ++r) {
		if (kvarr[r].key == key) {
			/* Do not allocate new memory for plugin */
			if (!bm)
				return kvarr[r].val;

			if (kvarr[r].val[0] == '~') {
				snprintf(buf, PATH_MAX, "%s%s", home, kvarr[r].val + 1);
				return buf;
			}

			return realpath(kvarr[r].val, buf);
		}
	}

	return NULL;
}

static int parsekvpair(kv **arr, char **envcpy, const char *envname, int *max)
{
	char *ptr = getenv(envname);
	int count = 0;

	if (!ptr || !*ptr)
		return 0;

	*envcpy = strdup(ptr);
	ptr = *envcpy;

	/* Count pairs */
	for (char *p = ptr; *p; ++p)
		if (*p == ';')
			++count;
	++count;

	*arr = calloc(count + 1, sizeof(kv));
	*max = count;

	int i = 0;

	while (*ptr && i < count) {
		char *sep = strchr(ptr, ';');

		if (sep)
			*sep = '\0';

		if (ptr[0] && ptr[1] == ':') {
			(*arr)[i].key = (uchar_t)ptr[0];
			(*arr)[i].val = ptr + 2;
			++i;
		}

		if (!sep)
			break;
		ptr = sep + 1;
	}

	*max = i;
	return i;
}

