/* ---------------------------------------------------------------- */
/* File operations                                                   */
/* ---------------------------------------------------------------- */

static bool xrm(char *fpath, bool use_trash);

static bool isselfileempty(void)
{
	struct stat sb;

	return !selpath || (stat(selpath, &sb) == -1) || (!sb.st_size);
}

static void endselection(bool endselmode)
{
	(void)endselmode;
	if (g_state.rangesel) {
		g_state.rangesel = 0;
	}
}

static bool xmktree(char *path, bool dir)
{
	char *p = path;
	char *slash = path;

	if (!p || !*p)
		return FALSE;

	/* Skip the first '/' */
	++p;

	while (*p != '\0') {
		if (*p == '/') {
			slash = p;
			*p = '\0';
		} else {
			++p;
			continue;
		}

		/* Create folder from path to '\0' inserted at p */
		if (mkdir(path, 0777) == -1 && errno != EEXIST) {
			*slash = '/';
			return FALSE;
		}

		/* Restore path */
		*slash = '/';
		++p;
	}

	if (dir) {
		if (mkdir(path, 0777) == -1 && errno != EEXIST)
			return FALSE;
	} else {
		int fd = open(path, O_CREAT, 0666);

		if (fd == -1 && errno != EEXIST)
			return FALSE;

		close(fd);
	}

	return TRUE;
}

static bool xchmod(const char *fpath, mode_t *mode)
{
	/* (Un)set (S_IXUSR | S_IXGRP | S_IXOTH) */
	(0100 & *mode) ? (*mode &= ~0111) : (*mode |= 0111);

	return (fchmodat(AT_FDCWD, fpath, *mode, 0) == 0);
}

static char *shquote(const char *s, char *out, size_t outlen)
{
	size_t len = 0;

	out[len++] = '\'';
	for (; *s && len < outlen - 6; ++s) {
		if (*s == '\'') {
			memcpy(out + len, "'\\''", 4);
			len += 4;
		} else
			out[len++] = *s;
	}
	out[len++] = '\'';
	out[len] = '\0';
	return out;
}

static bool xrm(char *fpath, bool use_trash)
{
	char cmd[PATH_MAX * 4 + 64];
	char q[PATH_MAX * 4 + 8];

	shquote(fpath, q, sizeof(q));
	if (use_trash && g_state.trash) {
		if (g_state.trash == 1)
			snprintf(cmd, sizeof(cmd), "trash-put -- %s", q);
		else
			snprintf(cmd, sizeof(cmd), "gio trash -- %s", q);
	} else
		snprintf(cmd, sizeof(cmd), "rm -rf -- %s", q);

	return run_sh(cmd, F_NORMAL | F_NOTRACE) == 0;
}

static void opstr(char *buf, const char *op)
{
	snprintf(buf, CMD_LEN_MAX, "xargs -0 sh -c '%s \"$0\" \"$@\" . < /dev/tty' < %s", op, selpath);
}

