		g_ctx[0].c_name[0] = '\0';

	lastname = g_ctx[0].c_name; /* last visited file name */

	xstrsncpy(g_ctx[0].c_path, ipath, PATH_MAX);
	path = g_ctx[0].c_path; /* current directory */

	g_ctx[0].c_fltr[0] = g_ctx[0].c_fltr[1] = '\0';
	g_ctx[0].c_cfg = cfg; /* current configuration */

	newpath[0] = '\0';

	presel = cfg.filtermode ? FILTER : 0;

	pdents = realloc(pdents, total_dents * sizeof(struct entry));
	if (!pdents)
		exit(1);

	pnamebuflen = NAMEBUF_INCR;
	pnamebuf = realloc(pnamebuf, pnamebuflen);
	if (!pnamebuf)
		exit(1);

begin:
	/*
	 * Can fail when permissions change while browsing.
	 * It's assumed that path IS a directory when we are here.
	 */
	if (chdir(path) == -1) {
		valid_parent(path, lastname);
		setdirwatch();
	}

	if ((presel == FILTER || watch) && inotify_wd >= 0) {
		inotify_rm_watch(inotify_fd, inotify_wd);
		inotify_wd = -1;
		watch = FALSE;
	}

	populate(path, lastname);

	if (presel != FILTER && inotify_wd == -1 && inotify_fd >= 0)
		inotify_wd = inotify_add_watch(inotify_fd, path,
				IN_ATTRIB | IN_CREATE | IN_DELETE | IN_DELETE_SELF
				| IN_MODIFY | IN_MOVE_SELF | IN_MOVED_FROM | IN_MOVED_TO
				| IN_EXCL_UNLINK);

	while (1) {
		/* Do not do a double redraw in filterentries */
		if ((presel != FILTER) || !filterset())
			redraw(path);

nochange:
		/* Exit if parent has exited */
		if (getppid() == 1)
			_exit(EXIT_FAILURE);

		/* If CWD is deleted or moved or perms changed, find an accessible parent */
		if (chdir(path) == -1)
			goto begin;

		sel = nextsel(presel);
		if (presel)
			presel = 0;

		switch (sel) {
		case SEL_CLICK:
			goto nochange;
		case SEL_BACK:
			dir = visit_parent(path, newpath, &presel);
			if (!dir)
				goto nochange;

			/* Save last working directory */
			xstrsncpy(lastdir, path, PATH_MAX);

			/* Save history */
			xstrsncpy(lastname, xbasename(path), NAME_MAX + 1);

			clearfilter();
			xstrsncpy(path, dir, PATH_MAX);

			setdirwatch();
			goto begin;
		case SEL_NAV_IN: // fallthrough
		case SEL_OPEN:
			/* Cannot descend in empty directories */
			if (!ndents)
				goto begin;

			pent = &pdents[cur];
			mkpath(path, pent->name, newpath);

			/* Visit directory */
			if (pent->flags & DIR_OR_DSLNK) {
				if (chdir(newpath) == -1) {
					printwarn(&presel);
					goto nochange;
				}

				cdprep(lastdir, lastname, path, newpath) ? (presel = FILTER) : (watch = TRUE);
				goto begin;
			}

			if (sel == SEL_NAV_IN && g_state.openonenter)
				goto nochange;

			/* Cannot use stale data in entry, file may be missing by now */
			if (stat(newpath, &sb) == -1) {
				printwarn(&presel);
				goto nochange;
			}

			/* Do not open non-regular files */
			if (!S_ISREG(sb.st_mode)) {
				printwait(messages[MSG_UNSUPPORTED], &presel);
				goto nochange;
			}

			if (!sb.st_size) {
				printwait(messages[MSG_EMPTY_FILE], &presel);
				goto nochange;
			}

			/* Invoke desktop opener as last resort */
			spawn(opener, newpath, NULL, NULL,
			      gcfg.cliopener ? F_CLI : (F_NOTRACE | F_NOSTDIN | F_NOWAIT));

			/* Move cursor to the next entry if not the last entry */
			if (g_state.autonext && cur != ndents - 1)
				move_cursor((cur + 1) % ndents, 0);
			if (cfg.filtermode) {
				presel = FILTER;
				clearfilter();
			}
			continue;
		case SEL_NEXT: // fallthrough
		case SEL_PREV: // fallthrough
		case SEL_PGDN: // fallthrough
		case SEL_CTRL_D: // fallthrough
		case SEL_PGUP: // fallthrough
		case SEL_CTRL_U: // fallthrough
		case SEL_HOME: // fallthrough
		case SEL_END: // fallthrough
		case SEL_FIRST: // fallthrough
		case SEL_JUMP: // fallthrough
		case SEL_YOUNG:
			if (ndents) {
				g_state.move = 1;
				handle_screen_move(sel);
			}
			break;
		case SEL_CDHOME: // fallthrough
		case SEL_CDBEGIN: // fallthrough
		case SEL_CDLAST: // fallthrough
		case SEL_CDROOT:
			dir = (sel == SEL_CDHOME) ? home
				: ((sel == SEL_CDBEGIN) ? ipath
				: ((sel == SEL_CDLAST) ? lastdir
				: "/" /* SEL_CDROOT */));

			if (!dir || !*dir) {
				printwait(messages[MSG_NOT_SET], &presel);
				goto nochange;
			}

			if (strcmp(path, dir) == 0) {
				if (dir == ipath) {
					if (cfg.filtermode)
						presel = FILTER;
					goto nochange;
				}
				dir = lastdir; /* Go to last dir on home/root key repeat */
			}

			if (chdir(dir) == -1) {
				presel = MSGWAIT;
				goto nochange;
			}

			/* SEL_CDLAST: dir pointing to lastdir */
			xstrsncpy(newpath, dir, PATH_MAX);

			cdprep(lastdir, lastname, path, newpath) ? (presel = FILTER) : (watch = TRUE);
			goto begin;
		case SEL_BMOPEN:
			if (!bmdir)
				goto nochange;
			xstrsncpy(newpath, bmdir, PATH_MAX);
			if (strcmp(path, newpath) == 0) {
				presel = FILTER;
				break;
			}
			cdprep(lastdir, lastname, path, newpath);
			presel = FILTER;
			goto begin;
		case SEL_REMOTE:
			printwait(messages[MSG_INSTALL_REMOTE], &presel);
			goto nochange;
		case SEL_CYCLE: // fallthrough
		case SEL_CYCLER: // fallthrough
		case SEL_CTX1: // fallthrough
		case SEL_CTX2: // fallthrough
		case SEL_CTX3: // fallthrough
		case SEL_CTX4: // fallthrough
		case SEL_CTX5: // fallthrough
		case SEL_CTX6: // fallthrough
		case SEL_CTX7: // fallthrough
		case SEL_CTX8:
			r = handle_context_switch(sel);
			if (r < 0)
				continue;
			savecurctx(path, ndents ? pdents[cur].name : NULL, r);

			/* Reset the pointers */
			path = g_ctx[r].c_path;
			lastdir = g_ctx[r].c_last;
			lastname = g_ctx[r].c_name;
			tmp = g_ctx[r].c_fltr;

			if (cfg.filtermode || ((tmp[0] == FILTER || tmp[0] == RFILTER) && tmp[1]))
				presel = FILTER;
			else
				watch = TRUE;

			goto begin;
		case SEL_MARK:
			free(mark);
			mark = strdup(path);
			printwait(mark, &presel);
			goto nochange;
		case SEL_BMARK:
		{
			char *bname = xreadline(xbasename(path), messages[MSG_BM_NAME]);

			if (bname && *bname && bmdir) {
				char lnk[PATH_MAX];

				mkpath(bmdir, bname, lnk);
				if (symlink(path, lnk) == -1) {
					printwarn(&presel);
					goto nochange;
				}
			}
			goto nochange;
		}
		case SEL_FLTR:
			/* Unwatch dir if we are still in a filtered view */
			if (inotify_wd >= 0) {
				inotify_rm_watch(inotify_fd, inotify_wd);
				inotify_wd = -1;
			}
			presel = filterentries(path, lastname);
			if (presel == ESC) {
				presel = 0;
				break;
			}
			if (presel == FILTER) { /* Refresh dir and filter again */
				goto begin;
			}
			goto nochange;
		case SEL_MFLTR: // fallthrough
		case SEL_HIDDEN: // fallthrough
		case SEL_DETAIL: // fallthrough
		case SEL_SORT:
			switch (sel) {
			case SEL_MFLTR:
				cfg.filtermode ^= 1;
				if (cfg.filtermode) {
					presel = FILTER;
					clearfilter();
					goto nochange;
				}

				watch = TRUE; // fallthrough
			case SEL_HIDDEN:
				if (sel == SEL_HIDDEN) {
					cfg.showhidden ^= 1;
					if (cfg.filtermode)
						presel = FILTER;
					clearfilter();
				}
				copycurname();
				goto begin;
			case SEL_DETAIL:
				cfg.showdetail ^= 1;
				break;
			default: /* SEL_SORT */
				r = set_sort_flags(get_input(messages[MSG_ORDER]));
				if (!r) {
					printwait(messages[MSG_INVALID_KEY], &presel);
					goto nochange;
				}
			}

			if (cfg.filtermode || filterset())
				presel = FILTER;

			if (ndents) {
				copycurname();

				if (r == 'd' || r == 'a') {
					presel = 0;
					goto begin;
				}

				entsort();
				move_cursor(ndents ? dentfind(lastname, ndents) : 0, 0);
			}
			continue;
		case SEL_STATS: // fallthrough
		case SEL_CHMODX:
			if (ndents) {
				mkpath(path, pdents[cur].name, newpath);

				if ((sel == SEL_STATS && !show_stats(path))
				    || (lstat(newpath, &sb) == -1)
				    || (sel == SEL_CHMODX && !xchmod(newpath, &sb.st_mode))) {
					printwarn(&presel);
					goto nochange;
				}

				if (sel == SEL_CHMODX)
					pdents[cur].mode ^= 0111;
			}
			break;
		case SEL_ARCHIVE: // fallthrough
		case SEL_OPENWITH: // fallthrough
		case SEL_NEW: // fallthrough
		case SEL_RENAME:
		{
			int fd, ret = 'n';

			if (!ndents && (sel == SEL_OPENWITH || sel == SEL_RENAME))
				break;

			if (sel != SEL_OPENWITH)
				endselection(TRUE);

			switch (sel) {
			case SEL_ARCHIVE:
				tmp = xreadline(pdents[cur].name, messages[MSG_ARCHIVE_NAME]);
				break;
			case SEL_OPENWITH:
				tmp = xreadline(NULL, messages[MSG_OPEN_WITH]);
				break;
			case SEL_NEW:
				r = get_input(messages[MSG_NEW_OPTS]);
				if (r == '\r')
					r = 'f';
				if (r == 'f' || r == 'd')
					tmp = xreadline(NULL, messages[MSG_NEW_PATH]);
				else if (r == 's' || r == 'h')
					tmp = xreadline(NULL, messages[MSG_LINK_PREFIX]);
				else
					tmp = NULL;
				break;
			default: /* SEL_RENAME */
				tmp = xreadline(pdents[cur].name, "");
				break;
			}

			if (!tmp || !*tmp || is_bad_len_or_dir(tmp))
				break;

			switch (sel) {
			case SEL_ARCHIVE:
				continue;
			case SEL_OPENWITH:
				copycurname();
				goto nochange;
			case SEL_RENAME:
				/* Skip renaming to same name */
				if (strcmp(tmp, pdents[cur].name) == 0) {
					tmp = xreadline(pdents[cur].name, messages[MSG_COPY_NAME]);
					if (!tmp || !tmp[0] || is_bad_len_or_dir(tmp)
					    || !strcmp(tmp, pdents[cur].name)) {
						cfg.filtermode ?  presel = FILTER : (statusbar(path), 0);
						copycurname();
						goto nochange;
					}
					ret = 'd';
				}
				break;
			default: /* SEL_NEW */
				break;
			}

			/* Open the descriptor to currently open directory */
			fd = open(path, O_RDONLY | O_DIRECTORY);
			if (fd == -1) {
				printwarn(&presel);
				goto nochange;
			}

			/* Check if another file with same name exists */
			if (fstatat(fd, tmp, &sb, AT_SYMLINK_NOFOLLOW) == 0) {
				if (sel == SEL_RENAME) {
					/* Overwrite file with same name? */
					if (!xconfirm(get_input(messages[MSG_OVERWRITE]))) {
						close(fd);
						break;
					}
				} else {
					/* Do nothing in case of NEW */
					close(fd);
					printwait(messages[MSG_EXISTS], &presel);
					goto nochange;
				}
			}

			if (sel == SEL_RENAME) {
				/* Rename the file */
				if (ret == 'd') {
					char cmd[PATH_MAX * 8];
					char q1[PATH_MAX * 4 + 8], q2[PATH_MAX * 4 + 8];

					snprintf(cmd, sizeof(cmd), "cp -rp -- %s %s",
						 shquote(pdents[cur].name, q1, sizeof(q1)),
						 shquote(tmp, q2, sizeof(q2)));
					run_sh(cmd, F_NORMAL | F_NOTRACE);
				} else if (renameat(fd, pdents[cur].name, fd, tmp) != 0) {
					close(fd);
					printwarn(&presel);
					goto nochange;
				}
				close(fd);
				xstrsncpy(lastname, tmp, NAME_MAX + 1);
			} else { /* SEL_NEW */
				close(fd);
				presel = 0;

				/* Check if it's a dir or file */
				if (r == 'f' || r == 'd') {
					mkpath(path, tmp, newpath);
					ret = xmktree(newpath, r == 'f' ? FALSE : TRUE);
				} else
					ret = 0;

				if (!ret)
					printwait(messages[MSG_FAILED], &presel);

				if (ret <= 0)
					goto nochange;

				if (r == 'f' || r == 'd')
					xstrsncpy(lastname, tmp, NAME_MAX + 1);
				else if (ndents) {
					if (cfg.filtermode)
						presel = FILTER;
					copycurname();
				}
				clearfilter();
			}

			goto begin;
		}
		case SEL_REDRAW:
			copycurname();
			goto begin;
		case SEL_SEL:
			if (!ndents)
				goto nochange;

			/* Toggle selection status */
			pdents[cur].flags ^= FILE_SELECTED;

			if (pdents[cur].flags & FILE_SELECTED) {
				++nselected;
				appendfpath(newpath, mkpath(path, pdents[cur].name, newpath));
				writesel(pselbuf, selbufpos - 1); /* Truncate NULL from end */
			} else {
				--nselected;
				rmfromselbuf(mkpath(path, pdents[cur].name, g_sel) ? g_sel : g_sel);
			}

			/* move cursor to the next entry if this is not the last entry */
			if (!g_state.stayonsel && !g_state.picked && cur != ndents - 1)
				move_cursor((cur + 1) % ndents, 0);
			break;
		case SEL_SELMUL:
			if (!ndents)
				goto nochange;

			g_state.selmode ^= 1;
			if (g_state.selmode) {
				g_state.rangesel = 1;
				firstsel = cur;
			} else {
				g_state.rangesel = 0;
				int a = MIN(firstsel, cur), b = MAX(firstsel, cur);

				for (int i = a; i <= b && i < ndents; ++i) {
					if (!(pdents[i].flags & FILE_SELECTED)) {
						pdents[i].flags |= FILE_SELECTED;
						++nselected;
						appendfpath(newpath, mkpath(path, pdents[i].name, newpath));
					}
				}
				if (nselected)
					writesel(pselbuf, selbufpos - 1);
			}
			break;
		case SEL_SELALL: // fallthrough
		case SEL_SELINV:
			if (!ndents)
				goto nochange;

			for (int i = 0; i < ndents; ++i) {
				if (sel == SEL_SELALL) {
					if (pdents[i].flags & FILE_SELECTED)
						continue;
				}
				pdents[i].flags ^= FILE_SELECTED;
				mkpath(path, pdents[i].name, newpath);
				if (pdents[i].flags & FILE_SELECTED) {
					++nselected;
					appendfpath(newpath, strlen(newpath) + 1);
				} else {
					--nselected;
					size_t l = strlen(newpath) + 1;

					for (size_t pos = 0; pos < selbufpos;) {
						size_t ll = strlen(pselbuf + pos) + 1;

						if (ll == l && !memcmp(pselbuf + pos, newpath, l)) {
							memmove(pselbuf + pos, pselbuf + pos + ll, selbufpos - pos - ll);
							selbufpos -= ll;
							break;
						}
						pos += ll;
					}
				}
			}
			flush_selection_file();
			break;
		case SEL_SELEDIT:
		case SEL_SELSIZE:
		case SEL_RENAMEMUL:
		case SEL_EDIT:
		case SEL_PLUGIN:
		case SEL_LOCK:
		case SEL_UMOUNT:
		case SEL_SESSIONS:
		case SEL_EXPORT:
		case SEL_LAUNCH:
		case SEL_PROMPT:
		case SEL_SHELL:
		case SEL_FIFO:
			goto nochange;
		case SEL_CP: // fallthrough
		case SEL_MV: // fallthrough
		case SEL_CPMVAS: // fallthrough
		case SEL_TRASH: // fallthrough
		case SEL_RM:
		{
			if (sel == SEL_TRASH || sel == SEL_RM) {
				if (!ndents)
					goto nochange;
				char prompt[PATH_MAX + 32];

				snprintf(prompt, sizeof(prompt), messages[MSG_RM_ONE], pdents[cur].name);
				r = get_input(prompt);
				if (!xconfirm(r)) {
					statusbar(path);
					place_cursor();
					goto nochange;
				}
				mkpath(path, pdents[cur].name, newpath);
				xrm(newpath, sel == SEL_TRASH);
				if (cur && cur == ndents - 1)
					--cur;
				copycurname();
				goto begin;
			}

			if (!nselected) {
				printwait(messages[MSG_0_SELECTED], &presel);
				goto nochange;
			}

			if (sel == SEL_CP)
				opstr(g_buf, g_state.advcp ? "cp -igRp" : "cp -iRp");
			else if (sel == SEL_MV)
				opstr(g_buf, g_state.advcp ? "mv -ig" : "mv -i");
			else
				goto nochange;

			run_sh(g_buf, F_NORMAL);
			clearselection();
			goto begin;
		}
		case SEL_HELP:
			show_help(path);
			continue;
		case SEL_AUTONEXT:
			g_state.autonext ^= 1;
			goto nochange;
		case SEL_TIMETYPE:
		{
			char prompt[64];

			snprintf(prompt, sizeof(prompt), messages[MSG_TIMETYPE],
				 (cfg.timetype == T_MOD) ? 'm' : ((cfg.timetype == T_ACCESS) ? 'a' : 'c'));
			r = get_input(prompt);

			if (r == 'a' || r == 'c' || r == 'm') {
				r = (r == 'm') ? T_MOD : ((r == 'a') ? T_ACCESS : T_CHANGE);
				if (cfg.timetype != (uint_t)r) {
					cfg.timetype = r;
				}
				copycurname();
				goto begin;
			} else
				printwait(messages[MSG_INVALID_KEY], &presel);
			goto nochange;
		}
		case SEL_QUITCTX: // fallthrough
		case SEL_QUITCD: // fallthrough
		case SEL_QUIT: // fallthrough
		case SEL_QUITERR:
			if (sel == SEL_QUITCTX) {
				int ctx = gcfg.curctx;

				for (r = (ctx - 1) & (CTX_MAX - 1);
				     (r != ctx) && !g_ctx[r].c_cfg.ctxactive;
				     r = ((r - 1) & (CTX_MAX - 1))) {
				};

				if (r != ctx) {
					g_ctx[ctx].c_cfg.ctxactive = 0;

					/* Switch to next active context */
					path = g_ctx[r].c_path;
					lastdir = g_ctx[r].c_last;
					lastname = g_ctx[r].c_name;

					cfg = g_ctx[r].c_cfg;

					gcfg.curctx = r;
					apply_cmpfns();
					setdirwatch();
					goto begin;
				}
			} else if (!g_state.forcequit) {
				for (r = 0; r < CTX_MAX; ++r)
					if (r != (int)gcfg.curctx && g_ctx[r].c_cfg.ctxactive) {
						r = get_input(messages[MSG_QUIT_ALL]);
						break;
					}

				if (!(r == CTX_MAX || xconfirm(r)))
					break;
			}

			/* CD on Quit */
			tmp = getenv("NNN_TMPFILE");
			if ((sel == SEL_QUITCD) || tmp)
				write_lastdir(path, tmp);

			return sel == SEL_QUITERR ? FALSE : TRUE;
		default:
			if (r == -1)
				r = 0;
			goto nochange;
		} /* switch (sel) */
	}
}

EOF
echo ok"}

actions.command:
cat >> /workspace/src/nnn.c <<'EOF'
/* ---------------------------------------------------------------- */
/* The main loop                                                     */
/* ---------------------------------------------------------------- */

static bool browse(char *ipath, const char *session, int pkey)
{
	char newpath[PATH_MAX] __attribute__((aligned(16)));
	char *path, *lastdir, *lastname, *dir, *tmp;
	pEntry pent;
	enum action sel;
	struct stat sb;
	int r = -1, presel;
	bool watch = FALSE;

	(void)session;
	(void)pkey;

	getmaxyx(stdscr, xlines, xcols);

	/* set-up first context */
	g_ctx[0].c_last[0] = '\0';
	lastdir = g_ctx[0].c_last; /* last visited directory */

	if (g_state.initfile) {
		xstrsncpy(g_ctx[0].c_name, xbasename(ipath), sizeof(g_ctx[0].c_name));
		xdirname(ipath);
	} else
		g_ctx[0].c_name[0] = '\0';

	lastname = g_ctx[0].c_name; /* last visited file name */

	xstrsncpy(g_ctx[0].c_path, ipath, PATH_MAX);
	path = g_ctx[0].c_path; /* current directory */

	g_ctx[0].c_fltr[0] = g_ctx[0].c_fltr[1] = '\0';
	g_ctx[0].c_cfg = cfg; /* current configuration */

	newpath[0] = '\0';

	presel = cfg.filtermode ? FILTER : 0;

	pdents = realloc(pdents, total_dents * sizeof(struct entry));
	if (!pdents)
		exit(1);

	pnamebuflen = NAMEBUF_INCR;
	pnamebuf = realloc(pnamebuf, pnamebuflen);
	if (!pnamebuf)
		exit(1);

begin:
	/*
	 * Can fail when permissions change while browsing.
	 * It's assumed that path IS a directory when we are here.
	 */
	if (chdir(path) == -1) {
		valid_parent(path, lastname);
		setdirwatch();
	}

	if ((presel == FILTER || watch) && inotify_wd >= 0) {
		inotify_rm_watch(inotify_fd, inotify_wd);
		inotify_wd = -1;
		watch = FALSE;
	}

	populate(path, lastname);

	if (presel != FILTER && inotify_wd == -1 && inotify_fd >= 0)
		inotify_wd = inotify_add_watch(inotify_fd, path,
				IN_ATTRIB | IN_CREATE | IN_DELETE | IN_DELETE_SELF
				| IN_MODIFY | IN_MOVE_SELF | IN_MOVED_FROM | IN_MOVED_TO
				| IN_EXCL_UNLINK);

	while (1) {
		/* Do not do a double redraw in filterentries */
		if ((presel != FILTER) || !filterset())
			redraw(path);

nochange:
		/* Exit if parent has exited */
		if (getppid() == 1)
			_exit(EXIT_FAILURE);

		/* If CWD is deleted or moved or perms changed, find an accessible parent */
		if (chdir(path) == -1)
			goto begin;

		sel = nextsel(presel);
		if (presel)
			presel = 0;

		switch (sel) {
		case SEL_CLICK:
			goto nochange;
		case SEL_BACK:
			dir = visit_parent(path, newpath, &presel);
			if (!dir)
				goto nochange;

			/* Save last working directory */
			xstrsncpy(lastdir, path, PATH_MAX);

			/* Save history */
			xstrsncpy(lastname, xbasename(path), NAME_MAX + 1);

			clearfilter();
			xstrsncpy(path, dir, PATH_MAX);

			setdirwatch();
			goto begin;
		case SEL_NAV_IN: // fallthrough
		case SEL_OPEN:
			/* Cannot descend in empty directories */
			if (!ndents)
				goto begin;

			pent = &pdents[cur];
			mkpath(path, pent->name, newpath);

			/* Visit directory */
			if (pent->flags & DIR_OR_DSLNK) {
				if (chdir(newpath) == -1) {
					printwarn(&presel);
					goto nochange;
				}

				cdprep(lastdir, lastname, path, newpath) ? (presel = FILTER) : (watch = TRUE);
				goto begin;
			}

			if (sel == SEL_NAV_IN && g_state.openonenter)
				goto nochange;

			/* Cannot use stale data in entry, file may be missing by now */
			if (stat(newpath, &sb) == -1) {
				printwarn(&presel);
				goto nochange;
			}

			/* Do not open non-regular files */
			if (!S_ISREG(sb.st_mode)) {
				printwait(messages[MSG_UNSUPPORTED], &presel);
				goto nochange;
			}

			if (!sb.st_size) {
				printwait(messages[MSG_EMPTY_FILE], &presel);
				goto nochange;
			}

			/* Invoke desktop opener as last resort */
			spawn(opener, newpath, NULL, NULL,
			      gcfg.cliopener ? F_CLI : (F_NOTRACE | F_NOSTDIN | F_NOWAIT));

			/* Move cursor to the next entry if not the last entry */
			if (g_state.autonext && cur != ndents - 1)
				move_cursor((cur + 1) % ndents, 0);
			if (cfg.filtermode) {
				presel = FILTER;
				clearfilter();
			}
			continue;
		case SEL_NEXT: // fallthrough
		case SEL_PREV: // fallthrough
		case SEL_PGDN: // fallthrough
		case SEL_CTRL_D: // fallthrough
		case SEL_PGUP: // fallthrough
		case SEL_CTRL_U: // fallthrough
		case SEL_HOME: // fallthrough
		case SEL_END: // fallthrough
		case SEL_FIRST: // fallthrough
		case SEL_JUMP: // fallthrough
		case SEL_YOUNG:
			if (ndents) {
				g_state.move = 1;
				handle_screen_move(sel);
			}
			break;
		case SEL_CDHOME: // fallthrough
		case SEL_CDBEGIN: // fallthrough
		case SEL_CDLAST: // fallthrough
		case SEL_CDROOT:
			dir = (sel == SEL_CDHOME) ? home
				: ((sel == SEL_CDBEGIN) ? ipath
				: ((sel == SEL_CDLAST) ? lastdir
				: "/" /* SEL_CDROOT */));

			if (!dir || !*dir) {
				printwait(messages[MSG_NOT_SET], &presel);
				goto nochange;
			}

			if (strcmp(path, dir) == 0) {
				if (dir == ipath) {
					if (cfg.filtermode)
						presel = FILTER;
					goto nochange;
				}
				dir = lastdir; /* Go to last dir on home/root key repeat */
			}

			if (chdir(dir) == -1) {
				presel = MSGWAIT;
				goto nochange;
			}

			/* SEL_CDLAST: dir pointing to lastdir */
			xstrsncpy(newpath, dir, PATH_MAX);

			cdprep(lastdir, lastname, path, newpath) ? (presel = FILTER) : (watch = TRUE);
			goto begin;
		case SEL_BMOPEN:
			if (!bmdir)
				goto nochange;
			xstrsncpy(newpath, bmdir, PATH_MAX);
			if (strcmp(path, newpath) == 0) {
				presel = FILTER;
				break;
			}
			cdprep(lastdir, lastname, path, newpath);
			presel = FILTER;
			goto begin;
		case SEL_REMOTE:
			printwait(messages[MSG_INSTALL_REMOTE], &presel);
			goto nochange;
		case SEL_CYCLE: // fallthrough
		case SEL_CYCLER: // fallthrough
		case SEL_CTX1: // fallthrough
		case SEL_CTX2: // fallthrough
		case SEL_CTX3: // fallthrough
		case SEL_CTX4: // fallthrough
		case SEL_CTX5: // fallthrough
		case SEL_CTX6: // fallthrough
		case SEL_CTX7: // fallthrough
		case SEL_CTX8:
			r = handle_context_switch(sel);
			if (r < 0)
				continue;
			savecurctx(path, ndents ? pdents[cur].name : NULL, r);

			/* Reset the pointers */
			path = g_ctx[r].c_path;
			lastdir = g_ctx[r].c_last;
			lastname = g_ctx[r].c_name;
			tmp = g_ctx[r].c_fltr;

			if (cfg.filtermode || ((tmp[0] == FILTER || tmp[0] == RFILTER) && tmp[1]))
				presel = FILTER;
			else
				watch = TRUE;

			goto begin;
		case SEL_MARK:
			free(mark);
			mark = strdup(path);
			printwait(mark, &presel);
			goto nochange;
		case SEL_BMARK:
		{
			char *bname = xreadline(xbasename(path), messages[MSG_BM_NAME]);

			if (bname && *bname && bmdir) {
				char lnk[PATH_MAX];

				mkpath(bmdir, bname, lnk);
				if (symlink(path, lnk) == -1) {
					printwarn(&presel);
					goto nochange;
				}
			}
			goto nochange;
		}
		case SEL_FLTR:
			/* Unwatch dir if we are still in a filtered view */
			if (inotify_wd >= 0) {
				inotify_rm_watch(inotify_fd, inotify_wd);
				inotify_wd = -1;
			}
			presel = filterentries(path, lastname);
			if (presel == ESC) {
				presel = 0;
				break;
			}
			if (presel == FILTER) { /* Refresh dir and filter again */
				goto begin;
			}
			goto nochange;
		case SEL_MFLTR: // fallthrough
		case SEL_HIDDEN: // fallthrough
		case SEL_DETAIL: // fallthrough
		case SEL_SORT:
			switch (sel) {
			case SEL_MFLTR:
				cfg.filtermode ^= 1;
				if (cfg.filtermode) {
					presel = FILTER;
					clearfilter();
					goto nochange;
				}

				watch = TRUE; // fallthrough
			case SEL_HIDDEN:
				if (sel == SEL_HIDDEN) {
					cfg.showhidden ^= 1;
					if (cfg.filtermode)
						presel = FILTER;
					clearfilter();
				}
				copycurname();
				goto begin;
			case SEL_DETAIL:
				cfg.showdetail ^= 1;
				break;
			default: /* SEL_SORT */
				r = set_sort_flags(get_input(messages[MSG_ORDER]));
				if (!r) {
					printwait(messages[MSG_INVALID_KEY], &presel);
					goto nochange;
				}
			}

			if (cfg.filtermode || filterset())
				presel = FILTER;

			if (ndents) {
				copycurname();

				if (r == 'd' || r == 'a') {
					presel = 0;
					goto begin;
				}

				entsort();
				move_cursor(ndents ? dentfind(lastname, ndents) : 0, 0);
			}
			continue;
		case SEL_STATS: // fallthrough
		case SEL_CHMODX:
			if (ndents) {
				mkpath(path, pdents[cur].name, newpath);

				if ((sel == SEL_STATS && !show_stats(path))
				    || (lstat(newpath, &sb) == -1)
				    || (sel == SEL_CHMODX && !xchmod(newpath, &sb.st_mode))) {
					printwarn(&presel);
					goto nochange;
				}

				if (sel == SEL_CHMODX)
					pdents[cur].mode ^= 0111;
			}
			break;
		case SEL_ARCHIVE: // fallthrough
		case SEL_OPENWITH: // fallthrough
		case SEL_NEW: // fallthrough
		case SEL_RENAME:
		{
			int fd, ret = 'n';

			if (!ndents && (sel == SEL_OPENWITH || sel == SEL_RENAME))
				break;

			if (sel != SEL_OPENWITH)
				endselection(TRUE);

			switch (sel) {
			case SEL_ARCHIVE:
				tmp = xreadline(pdents[cur].name, messages[MSG_ARCHIVE_NAME]);
				break;
			case SEL_OPENWITH:
				tmp = xreadline(NULL, messages[MSG_OPEN_WITH]);
				break;
			case SEL_NEW:
				r = get_input(messages[MSG_NEW_OPTS]);
				if (r == '\r')
					r = 'f';
				if (r == 'f' || r == 'd')
					tmp = xreadline(NULL, messages[MSG_NEW_PATH]);
				else if (r == 's' || r == 'h')
					tmp = xreadline(NULL, messages[MSG_LINK_PREFIX]);
				else
					tmp = NULL;
				break;
			default: /* SEL_RENAME */
				tmp = xreadline(pdents[cur].name, "");
				break;
			}

			if (!tmp || !*tmp || is_bad_len_or_dir(tmp))
				break;

			switch (sel) {
			case SEL_ARCHIVE:
				continue;
			case SEL_OPENWITH:
				copycurname();
				goto nochange;
			case SEL_RENAME:
				/* Skip renaming to same name */
				if (strcmp(tmp, pdents[cur].name) == 0) {
					tmp = xreadline(pdents[cur].name, messages[MSG_COPY_NAME]);
					if (!tmp || !tmp[0] || is_bad_len_or_dir(tmp)
					    || !strcmp(tmp, pdents[cur].name)) {
						cfg.filtermode ?  presel = FILTER : (statusbar(path), 0);
						copycurname();
						goto nochange;
					}
					ret = 'd';
				}
				break;
			default: /* SEL_NEW */
				break;
			}

			/* Open the descriptor to currently open directory */
			fd = open(path, O_RDONLY | O_DIRECTORY);
			if (fd == -1) {
				printwarn(&presel);
				goto nochange;
			}

			/* Check if another file with same name exists */
			if (fstatat(fd, tmp, &sb, AT_SYMLINK_NOFOLLOW) == 0) {
				if (sel == SEL_RENAME) {
					/* Overwrite file with same name? */
					if (!xconfirm(get_input(messages[MSG_OVERWRITE]))) {
						close(fd);
						break;
					}
				} else {
					/* Do nothing in case of NEW */
					close(fd);
					printwait(messages[MSG_EXISTS], &presel);
					goto nochange;
				}
			}

			if (sel == SEL_RENAME) {
				/* Rename the file */
				if (ret == 'd') {
					char cmd[PATH_MAX * 8];
					char q1[PATH_MAX * 4 + 8], q2[PATH_MAX * 4 + 8];

					snprintf(cmd, sizeof(cmd), "cp -rp -- %s %s",
						 shquote(pdents[cur].name, q1, sizeof(q1)),
						 shquote(tmp, q2, sizeof(q2)));
					run_sh(cmd, F_NORMAL | F_NOTRACE);
				} else if (renameat(fd, pdents[cur].name, fd, tmp) != 0) {
					close(fd);
					printwarn(&presel);
					goto nochange;
				}
				close(fd);
				xstrsncpy(lastname, tmp, NAME_MAX + 1);
			} else { /* SEL_NEW */
				close(fd);
				presel = 0;

				/* Check if it's a dir or file */
				if (r == 'f' || r == 'd') {
					mkpath(path, tmp, newpath);
					ret = xmktree(newpath, r == 'f' ? FALSE : TRUE);
				} else
					ret = 0;

				if (!ret)
					printwait(messages[MSG_FAILED], &presel);

				if (ret <= 0)
					goto nochange;

				if (r == 'f' || r == 'd')
					xstrsncpy(lastname, tmp, NAME_MAX + 1);
				else if (ndents) {
					if (cfg.filtermode)
						presel = FILTER;
					copycurname();
				}
				clearfilter();
			}

			goto begin;
		}
		case SEL_REDRAW:
			copycurname();
			goto begin;
		case SEL_SEL:
			if (!ndents)
				goto nochange;

			/* Toggle selection status */
			pdents[cur].flags ^= FILE_SELECTED;

			if (pdents[cur].flags & FILE_SELECTED) {
				++nselected;
				appendfpath(newpath, mkpath(path, pdents[cur].name, newpath));
				writesel(pselbuf, selbufpos - 1); /* Truncate NULL from end */
			} else {
				--nselected;
				rmfromselbuf(mkpath(path, pdents[cur].name, g_sel) ? g_sel : g_sel);
			}

			/* move cursor to the next entry if this is not the last entry */
			if (!g_state.stayonsel && !g_state.picked && cur != ndents - 1)
				move_cursor((cur + 1) % ndents, 0);
			break;
		case SEL_SELMUL:
			if (!ndents)
				goto nochange;

			g_state.selmode ^= 1;
			if (g_state.selmode) {
				g_state.rangesel = 1;
				firstsel = cur;
			} else {
				g_state.rangesel = 0;
				int a = MIN(firstsel, cur), b = MAX(firstsel, cur);

				for (int i = a; i <= b && i < ndents; ++i) {
					if (!(pdents[i].flags & FILE_SELECTED)) {
						pdents[i].flags |= FILE_SELECTED;
						++nselected;
						appendfpath(newpath, mkpath(path, pdents[i].name, newpath));
					}
				}
				if (nselected)
					writesel(pselbuf, selbufpos - 1);
			}
			break;
		case SEL_SELALL: // fallthrough
		case SEL_SELINV:
			if (!ndents)
				goto nochange;

			for (int i = 0; i < ndents; ++i) {
				if (sel == SEL_SELALL) {
					if (pdents[i].flags & FILE_SELECTED)
						continue;
				}
				pdents[i].flags ^= FILE_SELECTED;
				mkpath(path, pdents[i].name, newpath);
				if (pdents[i].flags & FILE_SELECTED) {
					++nselected;
					appendfpath(newpath, strlen(newpath) + 1);
				} else {
					--nselected;
					size_t l = strlen(newpath) + 1;

					for (size_t pos = 0; pos < selbufpos;) {
						size_t ll = strlen(pselbuf + pos) + 1;

						if (ll == l && !memcmp(pselbuf + pos, newpath, l)) {
							memmove(pselbuf + pos, pselbuf + pos + ll, selbufpos - pos - ll);
							selbufpos -= ll;
							break;
						}
						pos += ll;
					}
				}
			}
			flush_selection_file();
			break;
		case SEL_SELEDIT:
		case SEL_SELSIZE:
		case SEL_RENAMEMUL:
		case SEL_EDIT:
		case SEL_PLUGIN:
		case SEL_LOCK:
		case SEL_UMOUNT:
		case SEL_SESSIONS:
		case SEL_EXPORT:
		case SEL_LAUNCH:
		case SEL_PROMPT:
		case SEL_SHELL:
		case SEL_FIFO:
			goto nochange;
		case SEL_CP: // fallthrough
		case SEL_MV: // fallthrough
		case SEL_CPMVAS: // fallthrough
		case SEL_TRASH: // fallthrough
		case SEL_RM:
		{
			if (sel == SEL_TRASH || sel == SEL_RM) {
				if (!ndents)
					goto nochange;
				char prompt[PATH_MAX + 32];

				snprintf(prompt, sizeof(prompt), messages[MSG_RM_ONE], pdents[cur].name);
				r = get_input(prompt);
				if (!xconfirm(r)) {
					statusbar(path);
					place_cursor();
					goto nochange;
				}
				mkpath(path, pdents[cur].name, newpath);
				xrm(newpath, sel == SEL_TRASH);
				if (cur && cur == ndents - 1)
					--cur;
				copycurname();
				goto begin;
			}

			if (!nselected) {
				printwait(messages[MSG_0_SELECTED], &presel);
				goto nochange;
			}

			if (sel == SEL_CP)
				opstr(g_buf, g_state.advcp ? "cp -igRp" : "cp -iRp");
			else if (sel == SEL_MV)
				opstr(g_buf, g_state.advcp ? "mv -ig" : "mv -i");
			else
				goto nochange;

			run_sh(g_buf, F_NORMAL);
			clearselection();
			goto begin;
		}
		case SEL_HELP:
			show_help(path);
			continue;
		case SEL_AUTONEXT:
			g_state.autonext ^= 1;
			goto nochange;
		case SEL_TIMETYPE:
		{
			char prompt[64];

			snprintf(prompt, sizeof(prompt), messages[MSG_TIMETYPE],
				 (cfg.timetype == T_MOD) ? 'm' : ((cfg.timetype == T_ACCESS) ? 'a' : 'c'));
			r = get_input(prompt);

			if (r == 'a' || r == 'c' || r == 'm') {
				r = (r == 'm') ? T_MOD : ((r == 'a') ? T_ACCESS : T_CHANGE);
				if (cfg.timetype != (uint_t)r) {
					cfg.timetype = r;
				}
				copycurname();
				goto begin;
			} else
				printwait(messages[MSG_INVALID_KEY], &presel);
			goto nochange;
		}
		case SEL_QUITCTX: // fallthrough
		case SEL_QUITCD: // fallthrough
		case SEL_QUIT: // fallthrough
		case SEL_QUITERR:
			if (sel == SEL_QUITCTX) {
				int ctx = gcfg.curctx;

				for (r = (ctx - 1) & (CTX_MAX - 1);
				     (r != ctx) && !g_ctx[r].c_cfg.ctxactive;
				     r = ((r - 1) & (CTX_MAX - 1))) {
				};

				if (r != ctx) {
					g_ctx[ctx].c_cfg.ctxactive = 0;

					/* Switch to next active context */
					path = g_ctx[r].c_path;
					lastdir = g_ctx[r].c_last;
					lastname = g_ctx[r].c_name;

					cfg = g_ctx[r].c_cfg;

					gcfg.curctx = r;
					apply_cmpfns();
					setdirwatch();
					goto begin;
				}
			} else if (!g_state.forcequit) {
				for (r = 0; r < CTX_MAX; ++r)
					if (r != (int)gcfg.curctx && g_ctx[r].c_cfg.ctxactive) {
						r = get_input(messages[MSG_QUIT_ALL]);
						break;
					}

				if (!(r == CTX_MAX || xconfirm(r)))
					break;
			}

			/* CD on Quit */
			tmp = getenv("NNN_TMPFILE");
			if ((sel == SEL_QUITCD) || tmp)
				write_lastdir(path, tmp);

			return sel == SEL_QUITERR ? FALSE : TRUE;
		default:
			if (r == -1)
				r = 0;
			goto nochange;
		} /* switch (sel) */
	}
}

EOF
echo ok

output.arguments:
{"command":"cat >> /workspace/src/nnn.c <<'EOF'
/* ---------------------------------------------------------------- */
/* Initialization                                                    */
/* ---------------------------------------------------------------- */

static bool init_fcolors(void)
{
	char *f_colors = getenv("NNN_FCOLORS");

	if (!f_colors || !*f_colors)
		f_colors = (char *)gcolors;

	for (uchar_t id = C_BLK; *f_colors && id <= C_UND; ++id) {
		fcolors[id] = xchartohex(*f_colors) << 4;
		if (*++f_colors) {
			fcolors[id] += xchartohex(*f_colors);
			if (fcolors[id])
				init_pair(id, fcolors[id], -1);
		} else
			return FALSE;
		++f_colors;
	}

	return TRUE;
}

static bool initcurses(void *oldmask)
{
	char *colors = getenv("NNN_COLORS");

	if (g_state.picker) {
		if (!newterm(NULL, stderr, stdin)) {
			fprintf(stderr, "newterm!\n");
			return FALSE;
		}
	} else if (!initscr()) {
		fprintf(stderr, "initscr!\n");
		return FALSE;
	}

	cbreak();
	noecho();
	nonl();
	keypad(stdscr, TRUE);
	mousemask(BUTTON1_PRESSED | BUTTON2_PRESSED | BUTTON3_PRESSED | BUTTON4_PRESSED | BUTTON5_PRESSED,
		  (mmask_t *)oldmask);
	mouseinterval(0);
	curs_set(FALSE); /* Hide cursor */

	if (colors || !getenv("NO_COLOR")) {
		uint_t *pcode;
		bool ext = FALSE;

		start_color();
		use_default_colors();

		/* Initialize file colors */
		if (COLORS >= 256) {
			if (!(g_state.oldcolor || init_fcolors())) {
				exitcurses();
				fprintf(stderr, "NNN_FCOLORS\n");
				return FALSE;
			}
		} else
			g_state.oldcolor = 1;

		if (colors && *colors == '#') {
			char *sep = strchr(colors, ';');

			if (!g_state.oldcolor && COLORS >= 256) {
				++colors;
				ext = TRUE;

				/*
				 * If fallback colors are specified, set the separator
				 * to NULL so we don't interpret separator and fallback
				 * if fewer than CTX_MAX xterm 256 colors are specified.
				 */
				if (sep)
					*sep = '\0';
			} else {
				colors = sep; /* Detect if 8 colors fallback is appended */
				if (colors)
					++colors;
			}
		}

		/* Get and set the context colors */
		for (uchar_t i = 0; i < CTX_MAX; ++i) {
			pcode = &g_ctx[i].color;

			if (colors && *colors) {
				if (ext) {
					*pcode = xchartohex(*colors) << 4;
					if (*++colors)
						fcolors[i + 1] = *pcode += xchartohex(*colors);
					else { /* Each color code must be 2 hex symbols */
						exitcurses();
						fprintf(stderr, "NNN_COLORS\n");
						return FALSE;
					}
				} else
					*pcode = (*colors < '0' || *colors > '7') ? 4 : *colors - '0';
				++colors;
			} else
				*pcode = 4;

			init_pair(i + 1, *pcode, -1);
		}

		init_pair(C_PLAIN, -1, -1);
	}

	settimeout(); /* One second */
	set_escdelay(25);
	return TRUE;
}

static void usage(void)
{
	fprintf(stdout,
		"%s: nnn [OPTIONS] [PATH]\n\n"
		"The unorthodox terminal file manager.\n\n"
		"positional args:\n"
		"  PATH   start dir/file [default: .]\n\n"
		"optional args:\n"
