static bool create_dir(const char *path)
{
	if (!xdiraccess(path)) {
		if (errno != ENOENT)
			return FALSE;

		if (mkdir(path, 0777) == -1)
			return FALSE;
	}

	return TRUE;
}

static bool setup_config(void)
{
	size_t r, len;
	char *xdgcfg = getenv("XDG_CONFIG_HOME");
	bool xdg = FALSE;

	/* Set up configuration file paths */
	if (xdgcfg && xdgcfg[0]) {
		len = xstrlen(xdgcfg) + 1 + 20; /* add length of "/nnn/bookmarks" */
		xdg = TRUE;
	} else if (home)
		len = xstrlen(home) + 1 + 20; /* add length of "/.config/nnn/bookmarks" */
	else
		return FALSE;

	cfgpath = (char *)malloc(len + 16);
	if (!cfgpath)
		return FALSE;

	if (xdg) {
		xstrsncpy(cfgpath, xdgcfg, len);
		r = len - 13; /* subtract length of "/nnn/bookmarks" */
	} else {
		r = xstrsncpy(cfgpath, home, len);

		/* Create ~/.config */
		xstrsncpy(cfgpath + r - 1, "/.config", len - r);
		if (!create_dir(cfgpath))
			return FALSE;
		r += 8; /* length of "/.config" */
	}

	/* Create ~/.config/nnn */
	char tmp[PATH_MAX];

	snprintf(tmp, sizeof(tmp), "%s", cfgpath);
	snprintf(cfgpath, len + 16, "%s/nnn", tmp);
	if (!create_dir(cfgpath))
		return FALSE;

	char sub[PATH_MAX];

	snprintf(sub, sizeof(sub), "%s/bookmarks", cfgpath);
	if (!create_dir(sub))
		return FALSE;
	bmdir = strdup(sub);
	snprintf(sub, sizeof(sub), "%s/sessions", cfgpath);
	if (!create_dir(sub))
		return FALSE;
	sessiondir = strdup(sub);
	snprintf(sub, sizeof(sub), "%s/mounts", cfgpath);
	if (!create_dir(sub))
		return FALSE;
	mountdir = strdup(sub);
	snprintf(sub, sizeof(sub), "%s/plugins", cfgpath);
	if (!create_dir(sub))
		return FALSE;
	plgpath = strdup(sub);

	/* Set selection file path */
	if (!g_state.picker) {
		char *env_sel = getenv("NNN_SEL");

		if (env_sel)
			selpath = strdup(env_sel);
		else {
			snprintf(sub, sizeof(sub), "%s/.selection", cfgpath);
			selpath = strdup(sub);
		}
	}

	(void)r;
	return TRUE;
}

static void cleanup(void)
{
	if (selpath && !g_state.picker)
		unlink(selpath);
}

int main(int argc, char *argv[])
{
	char *arg = NULL;
	char *session = NULL;
	int opt, sort = 0, pkey = '\0';
	mmask_t mask;
	char *env_opts = getenv("NNN_OPTS");
	int env_opts_id = env_opts ? (int)xstrlen(env_opts) : -1;

	while ((opt = (env_opts_id > 0
		       ? env_opts[--env_opts_id]
		       : getopt(argc, argv, "aAb:BcCdDeEfF:gHiJKl:nNop:P:QrRs:St:T:uUVxz0h"))) != -1) {
		switch (opt) {
		case 'a':
			g_state.autofifo = 1;
			break;
		case 'A':
			gcfg.autoenter = 0;
			break;
		case 'b':
			if (env_opts_id < 0)
				arg = optarg;
			break;
		case 'B':
			g_state.usebsdtar = 1;
			break;
		case 'c':
			gcfg.cliopener = 1;
			break;
		case 'C':
			g_state.oldcolor = 1;
			break;
		case 'd':
			cfg.showdetail = 1;
			break;
		case 'D':
			g_state.dirctx = 1;
			break;
		case 'e':
			gcfg.useeditor = 1;
			break;
		case 'E':
			gcfg.waitedit = 1;
			break;
		case 'f':
			g_state.histfile = 1;
			break;
		case 'F':
			if (env_opts_id < 0) {
				fifopath = optarg;
				g_state.fifomode = 1;
			}
			break;
		case 'g':
			gcfg.regex = 1;
			filtertype = 2;
			break;
		case 'H':
			cfg.showhidden = 1;
			break;
		case 'i':
			gcfg.fileinfo = 1;
			break;
		case 'J':
			g_state.stayonsel = 1;
			break;
		case 'K':
			g_state.keycollide = 1;
			break;
		case 'l':
			if (env_opts_id < 0)
				scroll_lines = atoi(optarg);
			break;
		case 'n':
			cfg.filtermode = 1;
			break;
		case 'N':
			g_state.xprompt = 1;
			break;
		case 'o':
			g_state.openonenter = 1;
			break;
		case 'p':
			if (env_opts_id >= 0)
				break;

			g_state.picker = 1;
			if (!(optarg[0] == '-' && optarg[1] == '\0')) {
				int fd = open(optarg, O_WRONLY | O_CREAT, 0600);

				if (fd == -1) {
					perror(optarg);
					return EXIT_FAILURE;
				}

				close(fd);
				selpath = abspath(optarg, NULL, NULL);
				unlink(selpath);
			}
			break;
		case 'P':
			if (env_opts_id < 0 && !optarg[1])
				pkey = (uchar_t)optarg[0];
			break;
		case 'Q':
			g_state.forcequit = 1;
			break;
		case 'r':
			g_state.advcp = 1;
			break;
		case 'R':
			gcfg.rollover = 0;
			break;
		case 's':
			if (env_opts_id < 0)
				session = optarg;
			break;
		case 'S':
			g_state.prstssn = 1;
			if (!session) /* Support named persistent sessions */
				session = "@";
			break;
		case 't':
			if (env_opts_id < 0)
				idletimeout = atoi(optarg);
			break;
		case 'T':
			if (env_opts_id < 0)
				sort = (uchar_t)optarg[0];
			break;
		case 'u':
			gcfg.prefersel = 1;
			break;
		case 'U':
			g_state.uidgid = 1;
			break;
		case 'V':
			fprintf(stdout, "%s\n", VERSION);
			return EXIT_SUCCESS;
		case 'x':
			gcfg.x11 = 1;
			break;
		case 'z':
			gcfg.fuzzyorder = 1;
			filtertype = 1;
			break;
		case '0':
			g_state.pickraw = 1;
			break;
		case 'h':
			usage();
			return EXIT_SUCCESS;
		default:
			usage();
			return EXIT_FAILURE;
		}
		if (env_opts_id == 0)
			env_opts_id = -1;
	}

	(void)arg;
	(void)session;
	(void)pkey;

	namecmpfn = &xstricmp;
	entrycmpfn = &entrycmp;

	home = getenv("HOME");
	if (!home)
		home = "";
	homelen = (int)xstrlen(home);

	if (!setup_config())
		return EXIT_FAILURE;

	if (!initpath) {
		if (argc == optind) {
			/* Start in the current directory */
			char *startpath = getenv("PWD");

			initpath = (startpath && *startpath) ? strdup(startpath) : getcwd(NULL, 0);
			if (!initpath)
				initpath = "/";
		} else {
			arg = argv[optind];

			size_t len = xstrlen(arg);

			if (len > 7 && is_prefix(arg, "file://", 7)) {
				arg = arg + 7;
				len -= 7;
			}
			initpath = abspath(arg, NULL, NULL);
			if (!initpath) {
				perror("abspath");
				return EXIT_FAILURE;
			}

			/* If the file is hidden, enable hidden option */
			if (*xbasename(initpath) == '.')
				cfg.showhidden = 1;

			struct stat sb;

			if (stat(initpath, &sb) == -1) {
				bool dir = (arg[len - 1] == '/');

				if (!dir) {
					arg = xbasename(initpath);
					initpath = xdirname(initpath);
					g_state.initfile = 1;
				}
				if (!xmktree(initpath, TRUE)) {
					perror(initpath);
					return EXIT_FAILURE;
				}
			} else if (!S_ISDIR(sb.st_mode))
				g_state.initfile = 1;
		}
	}

	/* Edit text in EDITOR if opted (and opener is not all-CLI) */
	if (gcfg.useeditor && gcfg.cliopener)
		gcfg.useeditor = 0;

	enveditor = getenv("VISUAL");
	if (!enveditor)
		enveditor = getenv("EDITOR");
	editor = enveditor ? enveditor : "vi";

	pager = getenv("PAGER");
	if (!pager)
		pager = "less";
	shell = getenv("SHELL");
	if (!shell)
		shell = "sh";

	opener = getenv_nonempty("NNN_OPENER");
	if (!opener)
		opener = "xdg-open";

	parsekvpair(&bookmark, &bmsenv, "NNN_BMS", &maxbm);
	parsekvpair(&plug, &plugenv, "NNN_PLUG", &maxplug);

	inotify_fd = inotify_init1(IN_NONBLOCK);

	setlocale(LC_ALL, "");

	if (!initcurses(&mask))
		return EXIT_FAILURE;

	if (sort)
		set_sort_flags(sort);

	signal(SIGPIPE, SIG_IGN);

	int ret = browse(initpath, session, pkey);

	exitcurses();
	cleanup();

	if (g_state.picker && selbufpos) {
		/* print selection */
		if (!selpath) {
			for (size_t pos = 0; pos < selbufpos;) {
				size_t l = strlen(pselbuf + pos);

				fwrite(pselbuf + pos, 1, l, stdout);
				fputc(g_state.pickraw ? '\0' : '\n', stdout);
				pos += l + 1;
			}
		}
	}

	return ret ? EXIT_SUCCESS : EXIT_FAILURE;
}
