		case 'R':
			gcfg.rollover = 0;
			break;
		case 's':
			if (env_opts_id < 0)
				session = optarg;
			break;
		case 'S':
			g_state.prstssn = 1;
			if (!session) /* Support named persistent sessions */
				session = "@";
			break;
		case 't':
			if (env_opts_id < 0)
				idletimeout = atoi(optarg);
			break;
		case 'T':
			if (env_opts_id < 0)
				sort = (uchar_t)optarg[0];
			break;
		case 'u':
			gcfg.prefersel = 1;
			break;
		case 'U':
			g_state.uidgid = 1;
			break;
		case 'V':
			fprintf(stdout, "%s\n", VERSION);
			return EXIT_SUCCESS;
		case 'x':
			gcfg.x11 = 1;
			break;
		case 'z':
			gcfg.fuzzyorder = 1;
			filtertype = 1;
			break;
		case '0':
			g_state.pickraw = 1;
			break;
		case 'h':
			usage();
			return EXIT_SUCCESS;
		default:
			usage();
			return EXIT_FAILURE;
		}
		if (env_opts_id == 0)
			env_opts_id = -1;
	}

	(void)arg;
	(void)session;
	(void)pkey;

	namecmpfn = &xstricmp;
	entrycmpfn = &entrycmp;

	home = getenv("HOME");
	if (!home)
		home = "";
	homelen = (int)xstrlen(home);

	if (!setup_config())
		return EXIT_FAILURE;

	if (!initpath) {
		if (argc == optind) {
			/* Start in the current directory */
			char *startpath = getenv("PWD");

			initpath = (startpath && *startpath) ? strdup(startpath) : getcwd(NULL, 0);
			if (!initpath)
				initpath = "/";
		} else {
			arg = argv[optind];

			size_t len = xstrlen(arg);

			if (len > 7 && is_prefix(arg, "file://", 7)) {
				arg = arg + 7;
				len -= 7;
			}
			initpath = abspath(arg, NULL, NULL);
			if (!initpath) {
				perror("abspath");
				return EXIT_FAILURE;
			}

			/* If the file is hidden, enable hidden option */
			if (*xbasename(initpath) == '.')
				cfg.showhidden = 1;

			struct stat sb;

			if (stat(initpath, &sb) == -1) {
				bool dir = (arg[len - 1] == '/');

				if (!dir) {
					arg = xbasename(initpath);
					initpath = xdirname(initpath);
					g_state.initfile = 1;
				}
				if (!xmktree(initpath, TRUE)) {
					perror(initpath);
					return EXIT_FAILURE;
				}
			} else if (!S_ISDIR(sb.st_mode))
				g_state.initfile = 1;
		}
	}

	/* Edit text in EDITOR if opted (and opener is not all-CLI) */
	if (gcfg.useeditor && gcfg.cliopener)
		gcfg.useeditor = 0;

	enveditor = getenv("VISUAL");
	if (!enveditor)
		enveditor = getenv("EDITOR");
	editor = enveditor ? enveditor : "vi";

	pager = getenv("PAGER");
	if (!pager)
		pager = "less";
	shell = getenv("SHELL");
	if (!shell)
		shell = "sh";

	opener = getenv_nonempty("NNN_OPENER");
	if (!opener)
		opener = "xdg-open";

	parsekvpair(&bookmark, &bmsenv, "NNN_BMS", &maxbm);
	parsekvpair(&plug, &plugenv, "NNN_PLUG", &maxplug);

	inotify_fd = inotify_init1(IN_NONBLOCK);

	setlocale(LC_ALL, "");

	if (!initcurses(&mask))
		return EXIT_FAILURE;

	if (sort)
		set_sort_flags(sort);

	signal(SIGPIPE, SIG_IGN);

	int ret = browse(initpath, session, pkey);

	exitcurses();
	cleanup();

	if (g_state.picker && selbufpos) {
		/* print selection */
		if (!selpath) {
			for (size_t pos = 0; pos < selbufpos;) {
				size_t l = strlen(pselbuf + pos);

				fwrite(pselbuf + pos, 1, l, stdout);
				fputc(g_state.pickraw ? '\0' : '\n', stdout);
				pos += l + 1;
			}
		}
	}

	return ret ? EXIT_SUCCESS : EXIT_FAILURE;
}
