	char tmpfile[PATH_MAX];
	char tmpdir[PATH_MAX];

	get_tmpdir(tmpdir);
	snprintf(tmpfile, sizeof(tmpfile), "%s/.nnnXXXXXX", tmpdir);
	fd = mkstemp(tmpfile);
	if (fd == -1)
		return FALSE;

	/* Write the selected paths, one per line */
	for (size_t pos = 0; pos < selbufpos;) {
		size_t l = strlen(pselbuf + pos);

		if (write(fd, pselbuf + pos, l) != (ssize_t)l || write(fd, "\n", 1) != 1)
