static bool cpmv_rename(int choice, const char *path)
{
	int fd;
	size_t count = 0;
	char tmpfile[PATH_MAX];
	char tmpdir[PATH_MAX];

	get_tmpdir(tmpdir);
	snprintf(tmpfile, sizeof(tmpfile), "%s/.nnnXXXXXX", tmpdir);
	fd = mkstemp(tmpfile);
	if (fd == -1)
		return FALSE;

	/* Write the selected paths, one per line */
	for (size_t pos = 0; pos < selbufpos;) {
		size_t l = strlen(pselbuf + pos);

		if (write(fd, pselbuf + pos, l) != (ssize_t)l || write(fd, "\n", 1) != 1)
			break;
		++count;
		pos += l + 1;
	}
	close(fd);

	struct stat sb1, sb2;

	if (stat(tmpfile, &sb1) == -1) {
		unlink(tmpfile);
		return FALSE;
	}

	spawn(editor, tmpfile, NULL, NULL, F_CLI);

	if (stat(tmpfile, &sb2) == -1 || (sb1.st_mtime == sb2.st_mtime && sb1.st_size == sb2.st_size)) {
		unlink(tmpfile);
		return TRUE;
	}

	FILE *fp = fopen(tmpfile, "r");
	char line[PATH_MAX];
	size_t pos = 0;
	bool ret = TRUE;

	if (!fp) {
		unlink(tmpfile);
		return FALSE;
	}

	while (pos < selbufpos && fgets(line, sizeof(line), fp)) {
		size_t l = strlen(line);
		char *src = pselbuf + pos;
		char cmd[PATH_MAX * 8], q1[PATH_MAX * 4 + 8], q2[PATH_MAX * 4 + 8], dst[PATH_MAX];

		if (l && line[l - 1] == '\n')
			line[--l] = '\0';
		pos += strlen(src) + 1;
		if (!l || !strcmp(line, src))
			continue;
		if (line[0] != '/')
			mkpath(path, line, dst);
		else
			xstrsncpy(dst, line, PATH_MAX);
		snprintf(cmd, sizeof(cmd), "%s -- %s %s", (choice == 'c') ? "cp -iRp" : "mv -i",
			 shquote(src, q1, sizeof(q1)), shquote(dst, q2, sizeof(q2)));
		if (run_sh(cmd, F_NORMAL) != 0)
			ret = FALSE;
	}
	fclose(fp);
	unlink(tmpfile);
	(void)count;
	return ret;
}

