{"command":"cd /workspace/src; python3 - <<'EOF'
s = open('nnn.c').read()
helpers = r"""static bool getutil(const char *util)
{
	char *path = getenv("PATH");

	if (!util || !*util)
		return FALSE;

	if (strchr(util, '/'))
		return access(util, X_OK) == 0;

	if (!path)
		return FALSE;

	char *dup = strdup(path), *save = NULL;
	bool found = FALSE;

	for (char *p = strtok_r(dup, ":", &save); p; p = strtok_r(NULL, ":", &save)) {
		char full[PATH_MAX];

		snprintf(full, sizeof(full), "%s/%s", *p ? p : ".", util);
		if (access(full, X_OK) == 0) {
			found = TRUE;
			break;
		}
	}
	free(dup);
	return found;
}

static bool xdiraccess_warn(const char *path)
{
	DIR *dirp = opendir(path);

	if (!dirp) {
		printwarn(NULL);
		return FALSE;
	}

	closedir(dirp);
	return TRUE;
}

static void setexports(const char *path)
{
	char dvar[] = "d0";
	char fvar[] = "f0";

	(void)path;
	if (ndents) {
		setenv("nnn", pdents[cur].name, 1);
		xstrsncpy(g_ctx[gcfg.curctx].c_name, pdents[cur].name, NAME_MAX + 1);
	} else if (g_ctx[gcfg.curctx].c_name[0])
		g_ctx[gcfg.curctx].c_name[0] = '\0';

	for (uchar_t i = 0; i < CTX_MAX; ++i) {
		if (g_ctx[i].c_cfg.ctxactive) {
			dvar[1] = fvar[1] = '1' + i;
			setenv(dvar, (i == gcfg.curctx) ? path : g_ctx[i].c_path, 1);

			if (g_ctx[i].c_name[0]) {
				char buf[PATH_MAX];

				mkpath((i == gcfg.curctx) ? path : g_ctx[i].c_path, g_ctx[i].c_name, buf);
				setenv(fvar, buf, 1);
			}
		}
	}
	setenv("NNN_INCLUDE_HIDDEN", xitoa(cfg.showhidden), 1);
	setenv("NNN_PREFER_SELECTION", xitoa(gcfg.prefersel), 1);
}

static char *getreadline(const char *prompt)
{
	exitcurses();

	char *input = readline(prompt);

	refresh();

	if (input && input[0]) {
		add_history(input);
		xstrsncpy(g_buf, input, CMD_LEN_MAX);
		free(input);
		return g_buf;
	}

	free(input);
	return NULL;
}

static void seltofile(int fd, uint_t *pcount)
{
	uint_t count = 0;

	for (size_t pos = 0; pos < selbufpos;) {
		size_t l = strlen(pselbuf + pos);

		if (write(fd, pselbuf + pos, l) != (ssize_t)l || write(fd, "\n", 1) != 1)
			break;
		++count;
		pos += l + 1;
	}

	if (pcount)
		*pcount = count;
}

static uint_t lines_in_file(const char *file)
{
	FILE *fp = fopen(file, "r");
	uint_t count = 0;
	int c, last = '\n';

	if (!fp)
		return 0;

	while ((c = fgetc(fp)) != EOF) {
		if (c == '\n')
			++count;
		last = c;
	}
	if (last != '\n')
		++count;
	fclose(fp);
	return count;
}

static bool batch_rename_ok(void)
{
	return TRUE;
}

static bool batch_rename(const char *path)
{
	int fd1, fd2;
	uint_t count = 0, lines = 0;
	bool dir = FALSE, ret = FALSE;
	char foriginal[PATH_MAX] = {0};
	char buf[PATH_MAX * 3];
	int i = get_cur_or_sel();

	(void)path;
	if (!i)
		return ret;

	if (i == 'c') { /* Rename entries in current dir */
		selbufpos = 0;
		dir = TRUE;
	}

	fd1 = create_tmp_file();
	if (fd1 == -1)
		return ret;

	xstrsncpy(foriginal, g_tmpfpath, PATH_MAX);

	fd2 = create_tmp_file();
	if (fd2 == -1) {
		unlink(foriginal);
		close(fd1);
		return ret;
	}

	if (dir)
		for (i = 0; i < ndents; ++i)
			appendfpath(pdents[i].name, NAME_MAX);

	seltofile(fd1, &count);
	seltofile(fd2, NULL);
	close(fd2);
	close(fd1);

	if (dir) /* Don't retain dir entries in selection */
		selbufpos = 0;

	spawn((gcfg.waitedit && enveditor) ? enveditor : editor, g_tmpfpath, NULL, NULL, F_CLI);

	lines = lines_in_file(g_tmpfpath);
	if (!lines || (count != lines))
		goto finish;

	snprintf(buf, sizeof(buf), "paste -d'\\n' %s %s | sed 'N; /^\\(.*\\)\\n\\1$/!p;d' | "
		 "tr '\\n' '\\0' | xargs -0 -n2 sh -c 'mv -i \"$0\" \"$@\" < /dev/tty'",
		 foriginal, g_tmpfpath);
	run_sh(buf, F_CLI);
	ret = TRUE;

finish:
	unlink(foriginal);
	unlink(g_tmpfpath);

	return ret;
}

static bool editselection(void)
{
	bool ret = FALSE;
	int fd, lines = 0;
	ssize_t count;
	struct stat sb;
	time_t mtime;

	if (!selbufpos)
		return ret;

	fd = create_tmp_file();
	if (fd == -1)
		return ret;

	seltofile(fd, NULL);
	if (close(fd)) {
		unlink(g_tmpfpath);
		return ret;
	}

	/* Save the last modification time */
	if (stat(g_tmpfpath, &sb)) {
		unlink(g_tmpfpath);
		return ret;
	}
	mtime = sb.st_mtime;

	spawn((gcfg.waitedit && enveditor) ? enveditor : editor, g_tmpfpath, NULL, NULL, F_CLI);

	fd = open(g_tmpfpath, O_RDONLY);
	if (fd == -1) {
		unlink(g_tmpfpath);
		return ret;
	}

	fstat(fd, &sb);

	if (mtime == sb.st_mtime) {
		close(fd);
		unlink(g_tmpfpath);
		return TRUE;
	}

	lines = lines_in_file(g_tmpfpath);
	if (lines > nselected) {
		close(fd);
		unlink(g_tmpfpath);
		return ret;
	}

	nselected = 0;
	selbufpos = 0;

	char *buf = malloc(sb.st_size + 2);

	if (buf) {
		count = read(fd, buf, sb.st_size);
		if (count > 0) {
			buf[count] = '\0';
			char *save = NULL;

			for (char *p = strtok_r(buf, "\n", &save); p; p = strtok_r(NULL, "\n", &save)) {
				if (!*p)
					continue;
				appendfpath(p, strlen(p) + 1);
				++nselected;
			}
		}
		free(buf);
	}
	close(fd);
	unlink(g_tmpfpath);

	if (nselected)
		writesel(pselbuf, selbufpos - 1);
	else
		clearselection();

	return TRUE;
}

static void export_file_list(void)
{
	if (!ndents)
		return;

	struct entry *pdent = pdents;
	int fd = create_tmp_file();

	if (fd == -1)
		return;

	for (int r = 0; r < ndents; ++pdent, ++r) {
		if (write(fd, pdent->name, pdent->nlen - 1) != (pdent->nlen - 1))
			break;

		if ((r != ndents - 1) && (write(fd, "\n", 1) != 1))
			break;
	}

	close(fd);

	char tfile[PATH_MAX];

	xstrsncpy(tfile, g_tmpfpath, PATH_MAX);
	spawn(editor, tfile, NULL, NULL, F_CLI);

	if (xconfirm(get_input(messages[MSG_RM_TMP])))
		unlink(tfile);
}

static void lock_terminal(void)
{
	char *locker = getenv_nonempty("NNN_LOCKER");

	if (!locker)
		locker = getutil("vlock") ? "vlock" : (getutil("bashlock") ? "bashlock" : "cmatrix");
	spawn(locker, NULL, NULL, NULL, F_CLI);
}

static bool launch_app(char *newpath)
{
	int r = F_NORMAL;
	char *tmp = newpath;

	mkpath(plgpath, "launch", newpath);

	if (!getutil("fzf") || access(newpath, X_OK) < 0) {
		tmp = xreadline(NULL, messages[MSG_APP_NAME]);
		r = F_NOWAIT | F_NOTRACE | F_MULTI;
	}

	if (tmp && *tmp)
		spawn(tmp, (r == F_NORMAL) ? "0" : NULL, NULL, NULL, r);

	return FALSE;
}

static bool prompt_run(void)
{
	bool ret = FALSE;
	char *tmp;

	while (1) {
		if (g_state.xprompt || g_state.picker)
			tmp = xreadline(NULL, PROMPT);
		else
			tmp = getreadline("\n"PROMPT);

		if (tmp && *tmp) {
			free(lastcmd);
			lastcmd = strdup(tmp);
			ret = TRUE;
			spawn("sh", "-c", tmp, NULL, F_CLI | F_CONFIRM);
		} else
			break;
	}

	return ret;
}

static bool handle_cmd(enum action sel, const char *path, char *newpath)
{
	endselection(FALSE);

	if (sel == SEL_LAUNCH)
		return launch_app(newpath);

	setexports(path);

	if (sel == SEL_PROMPT)
		return prompt_run();

	/* Set nnn nesting level */
	char *tmp = getenv("NNNLVL");
	int r = tmp ? atoi(tmp) : 0;

	setenv("NNNLVL", xitoa(r + 1), 1);
	spawn(shell, NULL, NULL, NULL, F_CLI);
	setenv("NNNLVL", xitoa(r), 1);
	return TRUE;
}

static bool is_suffix(const char *str, const char *suffix)
{
	size_t l = strlen(str), ls = strlen(suffix);

	return l >= ls && !strcmp(str + l - ls, suffix);
}

static void get_archive_cmd(char *cmd, const char *archive)
{
	const char *c;

	if (getutil("atool"))
		c = "atool -a";
	else if (getutil("bsdtar"))
		c = "bsdtar -acvf";
	else if (is_suffix(archive, ".zip"))
		c = "zip -r";
	else
		c = "tar -acvf";

	xstrsncpy(cmd, c, 64);
}

static void archive_selection(const char *cmd, const char *archive)
{
	char *buf = malloc(CMD_LEN_MAX);
	char q[PATH_MAX * 4 + 8];

	if (!buf)
		return;

	flush_selection_file();
	snprintf(buf, CMD_LEN_MAX,
		 "xargs -0 %s %s < '%s'", cmd, shquote(archive, q, sizeof(q)), selpath);
	run_sh(buf, F_NORMAL | F_CONFIRM);
	free(buf);
}

static bool remote_mount(char *newpath, int *presel)
{
	bool r = getutil("rclone"), s = getutil("sshfs");
	int opt;
	char *env, *tmp;
	uchar_t flag = F_CLI;

	if (!(r || s)) {
		printwait(messages[MSG_INSTALL_REMOTE], presel);
		return FALSE;
	}

	if (r && s)
		opt = get_input(messages[MSG_REMOTE_OPTS]);
	else
		opt = (!s) ? 'r' : 's';

	if (opt == 's')
		env = getenv_nonempty("NNN_SSHFS") ? getenv("NNN_SSHFS") : "sshfs";
	else if (opt == 'r') {
		flag |= F_NOWAIT | F_NOTRACE;
		env = getenv_nonempty("NNN_RCLONE") ? getenv("NNN_RCLONE") : "rclone mount";
	} else {
		printwait(messages[MSG_INVALID_KEY], presel);
		return FALSE;
	}

	tmp = xreadline(NULL, "host[:dir] > ");
	if (!tmp[0]) {
		printwait(messages[MSG_CANCEL], presel);
		return FALSE;
	}

	char host[PATH_MAX], remote[PATH_MAX], mntpath[PATH_MAX];
	char *div = strchr(tmp, ':');

	xstrsncpy(host, tmp, PATH_MAX);
	if (div) {
		host[div - tmp] = '\0';
		xstrsncpy(remote, tmp, PATH_MAX);
	} else if (opt == 'r') {
		snprintf(remote, PATH_MAX, "%s:", tmp);
	} else
		xstrsncpy(remote, tmp, PATH_MAX);

	mkpath(mountdir, host, mntpath);
	if (!xdiraccess(mntpath) && mkdir(mntpath, 0777) == -1) {
		printwarn(presel);
		return FALSE;
	}

	if (spawn(env, remote, mntpath, NULL, flag)) {
		printwait(messages[MSG_FAILED], presel);
		rmdir(mntpath);
		return FALSE;
	}

	xstrsncpy(newpath, mntpath, PATH_MAX);
	return TRUE;
}

static bool unmount(char *name, char *newpath, int *presel, char *currentpath)
{
	static char cmd[] = "fusermount3";
	static bool found = FALSE;
	char *tmp = name;
	struct stat sb, psb;
	bool child = FALSE;
	bool parent = FALSE;
	bool hovered = FALSE;

	/* On Ubuntu it's fusermount */
	if (!found && !getutil(cmd)) {
		cmd[10] = '\0';
		found = TRUE;
	}

	if (tmp && strcmp(mountdir, currentpath) == 0) {
		mkpath(mountdir, tmp, newpath);
		child = lstat(newpath, &sb) != -1;
		parent = lstat(xdirname(newpath), &psb) != -1;
		if (!child && !parent) {
			*presel = MSGWAIT;
			return FALSE;
		}
	}

	if (!tmp || !child || !S_ISDIR(sb.st_mode) || (child && parent && sb.st_dev == psb.st_dev)) {
		tmp = xreadline(NULL, messages[MSG_HOSTNAME]);
		if (!tmp[0])
			return FALSE;
		if (tmp[0] == '-' && !tmp[1]) {
			if (!name || !*name) {
				*presel = MSGWAIT;
				return FALSE;
			}
			tmp = name;
			hovered = TRUE;
		}
	}

	if (hovered)
		mkpath(currentpath, tmp, newpath);
	else
		mkpath(mountdir, tmp, newpath);

	if (!xdiraccess_warn(newpath)) {
		*presel = MSGWAIT;
		return FALSE;
	}

	if (spawn(cmd, "-qu", newpath, NULL, F_NORMAL)) {
		if (!xconfirm(get_input(messages[MSG_LAZY])))
			return FALSE;

		if (spawn(cmd, "-quz", newpath, NULL, F_NORMAL)) {
			printwait(messages[MSG_FAILED], presel);
			return FALSE;
		}
	}

	if (rmdir(newpath) == -1) {
		printwarn(presel);
		return FALSE;
	}

	return TRUE;
}

/* ---- Sessions ---- */

static bool save_session(const char *sname, const char *path, const char *curname, int *presel)
{
	char spath[PATH_MAX];
	FILE *fp;

	if (!sessiondir)
		return FALSE;

	/* Update the current context */
	xstrsncpy(g_ctx[gcfg.curctx].c_path, path, PATH_MAX);
	if (curname)
		xstrsncpy(g_ctx[gcfg.curctx].c_name, curname, NAME_MAX + 1);
	g_ctx[gcfg.curctx].c_cfg = cfg;

	mkpath(sessiondir, sname, spath);
	fp = fopen(spath, "wb");
	if (!fp) {
		printwarn(presel);
		return FALSE;
	}
	fchmod(fileno(fp), 0600);

	fprintf(fp, "NNNSSN1\n%u\n", (uint_t)gcfg.curctx);
	for (int i = 0; i < CTX_MAX; ++i) {
		settings *c = &g_ctx[i].c_cfg;

		fwrite(c, sizeof(*c), 1, fp);
		fwrite(g_ctx[i].c_path, PATH_MAX, 1, fp);
		fwrite(g_ctx[i].c_last, PATH_MAX, 1, fp);
		fwrite(g_ctx[i].c_name, NAME_MAX + 1, 1, fp);
		fwrite(g_ctx[i].c_fltr, REGEX_MAX, 1, fp);
	}
	fclose(fp);
	return TRUE;
}

static bool load_session(const char *sname, char **path, char **lastdir, char **lastname, bool restore)
{
	char spath[PATH_MAX];
	FILE *fp;
	char hdr[16];
	uint_t curctx = 0;
	context tmpctx[CTX_MAX];

	if (!sessiondir)
		return FALSE;

	mkpath(sessiondir, sname, spath);
	fp = fopen(spath, "rb");
	if (!fp)
		return FALSE;

	if (!fgets(hdr, sizeof(hdr), fp) || strcmp(hdr, "NNNSSN1\n") || fscanf(fp, "%u\n", &curctx) != 1
	    || curctx >= CTX_MAX) {
		fclose(fp);
		return FALSE;
	}

	memset(tmpctx, 0, sizeof(tmpctx));
	for (int i = 0; i < CTX_MAX; ++i) {
		if (fread(&tmpctx[i].c_cfg, sizeof(settings), 1, fp) != 1
		    || fread(tmpctx[i].c_path, PATH_MAX, 1, fp) != 1
		    || fread(tmpctx[i].c_last, PATH_MAX, 1, fp) != 1
		    || fread(tmpctx[i].c_name, NAME_MAX + 1, 1, fp) != 1
		    || fread(tmpctx[i].c_fltr, REGEX_MAX, 1, fp) != 1) {
			fclose(fp);
			return FALSE;
		}
		tmpctx[i].color = g_ctx[i].color;
	}
	fclose(fp);

	if (!tmpctx[curctx].c_cfg.ctxactive)
		return FALSE;

	memcpy(g_ctx, tmpctx, sizeof(g_ctx));
	gcfg.curctx = curctx;
	cfg = g_ctx[curctx].c_cfg;
	apply_cmpfns();

	*path = g_ctx[curctx].c_path;
	*lastdir = g_ctx[curctx].c_last;
	*lastname = g_ctx[curctx].c_name;

	if (restore)
		unlink(spath);

	return TRUE;
}

/* ---- Plugins ---- */

#define F_PAGE 0x100

static void run_cmd_as_plugin(const char *file, ushort flags)
{
	size_t len;
	char cmd[CMD_LEN_MAX];

	xstrsncpy(cmd, file, PATH_MAX);

	len = xstrlen(cmd);
	if (len > 1 && cmd[len - 1] == '*') {
		flags &= ~F_CONFIRM; /* Skip user confirmation */
		cmd[len - 1] = '\0'; /* Get rid of trailing no confirmation symbol */
		--len;
	}

	if (flags & F_PAGE) {
		int fd = create_tmp_file();

		if (fd == -1)
			return;

		pid_t pid = fork();

		if (pid == 0) {
			dup2(fd, STDOUT_FILENO);
			dup2(fd, STDERR_FILENO);
			close(fd);
			execl("/bin/sh", "sh", "-c", cmd, (char *)NULL);
			_exit(EXIT_SUCCESS);
		} else if (pid > 0)
			waitpid(pid, NULL, 0);
		close(fd);

		char tfile[PATH_MAX];

		xstrsncpy(tfile, g_tmpfpath, PATH_MAX);
		spawn(pager, tfile, NULL, NULL, F_CLI | F_TTY);
		unlink(tfile);
	} else
		spawn("sh", "-c", cmd, NULL, flags & ~F_MULTI);
}

static ssize_t read_nointr(int fd, void *buf, size_t count)
{
	ssize_t len;

	do
		len = read(fd, buf, count);
	while (len == -1 && errno == EINTR);

	return len;
}

static void readpipe(int fd, char **path, char **lastname, char **lastdir)
{
	char ctx, *nextpath = NULL;
	char buf[PATH_MAX + 1];

	if (read_nointr(fd, buf, 1) != 1)
		return;

	if (buf[0] == '-') { /* Clear selection on '-' */
		clearselection();
		if (read_nointr(fd, buf, 1) != 1)
			return;
	}

	if (buf[0] == '+') {
		int r;

		for (r = 0; r < CTX_MAX; ++r)
			if (!g_ctx[r].c_cfg.ctxactive)
				break;
		if (r == CTX_MAX)
			r = gcfg.curctx;
		ctx = (char)(r + 1);
	} else if (buf[0] < '0')
		return;
	else {
		ctx = buf[0] - '0';
		if (ctx > CTX_MAX)
			return;
	}

	if (read_nointr(fd, buf, 1) != 1)
		return;

	char op = buf[0];

	if (op == 'c') {
		ssize_t len = read_nointr(fd, buf, PATH_MAX);

		if (len <= 0)
			return;

		buf[len] = '\0'; /* Terminate the path read */
		if (buf[0] == '/') {
			nextpath = buf;
			len = xstrlen(buf);
			while (--len && (buf[len] == '/')) /* Trim all trailing '/' */
				buf[len] = '\0';
		}
	}

	if (nextpath) {
		if (ctx == 0 || ctx == (char)(gcfg.curctx + 1)) { /* Same context */
			clearfilter();
			xstrsncpy(*lastdir, *path, PATH_MAX);
			xstrsncpy(*path, nextpath, PATH_MAX);
		} else { /* New context */
			int r = ctx - 1;

			/* Deactivate the new context and build from scratch */
			g_ctx[r].c_cfg.ctxactive = 0;
			savecurctx(nextpath, NULL, r);
			*path = g_ctx[r].c_path;
			*lastdir = g_ctx[r].c_last;
			*lastname = g_ctx[r].c_name;
		}
	}
}

static bool run_plugin(char **path, const char *file, char *runfile, char **lastname, char **lastdir)
{
	pid_t p;
	bool cmd_as_plugin = FALSE;
	ushort flags = 0;

	if (!g_pipepath[0])
		snprintf(g_pipepath, PATH_MAX, "/tmp/nnn-pipe.%d", (int)getpid());

	setenv("NNN_PIPE", g_pipepath, 1);
	setexports(*path);

	/* Check for run-cmd-as-plugin mode */
	if (*file == '!') {
		flags = F_MULTI | F_CONFIRM;
		++file;

		/* Check if output should be paged */
		if (*file == '|') {
			flags |= F_PAGE;
			++file;
		} else if (*file == '&') { /* Check if GUI flags are to be used */
			flags = F_NOTRACE | F_NOWAIT;
			++file;
		}

		if (!*file)
			return FALSE;

		if ((flags & F_NOTRACE) || (flags & F_PAGE)) {
			run_cmd_as_plugin(file, flags);
			return TRUE;
		}

		cmd_as_plugin = TRUE;
	}

	unlink(g_pipepath);
	if (mkfifo(g_pipepath, 0600) != 0)
		return FALSE;

	exitcurses();

	p = fork();

	if (!p) { // In child
		int wfd = open(g_pipepath, O_WRONLY | O_CLOEXEC);

		if (wfd == -1)
			_exit(EXIT_FAILURE);

		if (!cmd_as_plugin) {
			char *sel = NULL;
			char std[2] = "-";
			char pbuf[PATH_MAX];

			/* Generate absolute path to plugin */
			mkpath(plgpath, file, pbuf);

			if (g_state.picker)
				sel = selpath ? selpath : std;

			if (runfile && runfile[0])
				spawn(pbuf, runfile, *path, sel, 0);
			else
				spawn(pbuf, NULL, *path, sel, 0);
		} else
			run_cmd_as_plugin(file, flags);

		close(wfd);
		_exit(EXIT_SUCCESS);
	}

	int rfd;

	do
		rfd = open(g_pipepath, O_RDONLY);
	while (rfd == -1 && errno == EINTR);

	if (rfd >= 0) {
		readpipe(rfd, path, lastname, lastdir);
		close(rfd);
	}

	/* wait for the child to finish. no zombies allowed */
	waitpid(p, NULL, 0);

	refresh();

	unlink(g_pipepath);

	return TRUE;
}

