}

/* Returns TRUE on success; for 'x' the destination dir is left in g_buf */
static bool handle_archive(char *fpath, const char *dir, int op, int *presel)
{
	char cmd[PATH_MAX * 3];
	char q1[PATH_MAX * 4 + 8], q2[PATH_MAX * 4 + 8];
	bool atool = getutil("atool"), bsdtar = getutil("bsdtar");

	if (op == 'x') {
		char *name = xreadline(xbasename(fpath), messages[MSG_NEW_PATH]);
		char dest[PATH_MAX];

		if (!name || !*name) {
			printwait(messages[MSG_CANCEL], presel);
			return FALSE;
		}

		if (name[0] == '/')
			xstrsncpy(dest, name, PATH_MAX);
		else
			mkpath(dir, name, dest);

		struct stat sb;

		if (stat(dest, &sb) == 0) {
			if (!S_ISDIR(sb.st_mode)) {
				errno = ENOTDIR;
				printwarn(presel);
				return FALSE;
			}
		} else if (!xmktree(dest, TRUE)) {
			printwarn(presel);
			return FALSE;
		}

		if (atool)
			snprintf(cmd, sizeof(cmd), "atool -X %s %s", shquote(dest, q2, sizeof(q2)),
				 shquote(fpath, q1, sizeof(q1)));
		else if (bsdtar)
			snprintf(cmd, sizeof(cmd), "bsdtar -xf %s -C %s", shquote(fpath, q1, sizeof(q1)),
				 shquote(dest, q2, sizeof(q2)));
		else if (is_suffix(fpath, ".zip") || is_suffix(fpath, ".ZIP"))
			snprintf(cmd, sizeof(cmd), "unzip -qq %s -d %s", shquote(fpath, q1, sizeof(q1)),
				 shquote(dest, q2, sizeof(q2)));
		else
			snprintf(cmd, sizeof(cmd), "tar -xf %s -C %s", shquote(fpath, q1, sizeof(q1)),
				 shquote(dest, q2, sizeof(q2)));

		run_sh(cmd, F_NORMAL | F_NOTRACE);
		xstrsncpy(g_buf, dest, PATH_MAX);
		return TRUE;
	}

	/* List */
	if (atool)
		snprintf(cmd, sizeof(cmd), "atool -l %s", shquote(fpath, q1, sizeof(q1)));
	else if (bsdtar)
		snprintf(cmd, sizeof(cmd), "bsdtar -tvf %s", shquote(fpath, q1, sizeof(q1)));
	else if (is_suffix(fpath, ".zip") || is_suffix(fpath, ".ZIP"))
		snprintf(cmd, sizeof(cmd), "unzip -l %s", shquote(fpath, q1, sizeof(q1)));
	else
		snprintf(cmd, sizeof(cmd), "tar -tvf %s", shquote(fpath, q1, sizeof(q1)));

	run_cmd_as_plugin(cmd, F_PAGE);
	return TRUE;
}

